 40	import type { CachedMcpServer, McpTool, McpToolCache } from "./tool-cache.js";
 41	
 42	const logger = createLogger("mcp-proxy");
 43	
 44	export type DirectToolExecutionOptions = {
 45		organizationId: string;
 46		conversationId?: string;
 47		channelId?: string;
 48		teamId?: string;
 49		connectionId?: string;
 50		platform?: string;
 51		source?: string;
 52		deploymentName?: string;
 53	} & PendingAdminGrant;
 54	
 55	export class McpProxy {
 56		// Tool-approval cards may sit in-thread for a long time before the user
 57		// actually clicks (Slack notifications, async review, etc.). The pending
 58		// invocation key holds the args needed to execute the tool after approval;
 59		// 24h gives users a realistic window to respond. Anything shorter silently
 60		// drops late clicks (the take-on-claim returns null and the click no-ops).
 61		private readonly PENDING_TOOL_TTL = 24 * 60 * 60; // 24 hours
 62		private app: Hono;
 63		private readonly toolCache?: McpToolCache;
 64		/** @internal Used by the route-handler modules (proxy-forward, proxy-rest-routes). */
 65		readonly grantStore?: GrantStore;
 66		/** @internal Used by the route-handler modules (proxy-forward, proxy-rest-routes). */
 67		readonly agentSettingsStore?: AgentSettingsStore;
 68		/** @internal Used by the route-handler modules (proxy-forward, proxy-rest-routes). */
 69		readonly guardrailRegistry?: GuardrailRegistry;
 70		/** @internal Upstream transport client (sessions, credentials, egress). */
 71		readonly upstream: McpUpstreamClient;
 72	
 73		/** Callback invoked when a tool call is blocked for approval. */
 74		public onToolBlocked?: (
 75			requestId: string,
 76			agentId: string,
 77			userId: string,
 78			mcpId: string,
 79			toolName: string,
 80			args: Record<string, unknown>,
 81			grantPattern: string,
 82			channelId: string,
 83			conversationId: string,
 84			teamId: string | undefined,
 85			connectionId: string | undefined,
 86			platform: string | undefined,
 87			source: string | undefined,
 88		) => Promise<void>;
 89	
 90		constructor(
 91			readonly configService: McpConfigSource,
 92			options: {
 93				toolCache?: McpToolCache;
 94				grantStore?: GrantStore;
 95				/** Source of per-agent guardrail enable lists for the pre-tool stage. */
 96				agentSettingsStore?: AgentSettingsStore;
 97				/** Shared registry of guardrails; pre-tool stage entries are queried. */
 98				guardrailRegistry?: GuardrailRegistry;
 99			},
100		) {
101			this.toolCache = options.toolCache;
102			this.grantStore = options.grantStore;
103			this.agentSettingsStore = options.agentSettingsStore;
104			this.guardrailRegistry = options.guardrailRegistry;
105			this.upstream = new McpUpstreamClient();
106			this.app = new Hono();
107			this.setupRoutes();
108			logger.debug("MCP proxy initialized");
109		}
110	
111		getApp(): Hono {
112			return this.app;
113		}
114	
115		/**
116		 * Execute an MCP tool call directly (internal use, no HTTP auth).
117		 * Used by the interaction bridge to execute tool calls after user approval.
118		 */
119		async executeToolDirect(
120			agentId: string,
121			userId: string,
122			mcpId: string,
123			toolName: string,
124			args: Record<string, unknown>,
125			options: DirectToolExecutionOptions,
126		): Promise<{
127			content: Array<{ type: string; text: string }>;
128			isError: boolean;
129		}> {
130			return runWithOrganizationContext(options?.organizationId, () =>
131				this.executeToolDirectScoped(
132					agentId,
133					userId,
134					mcpId,
135					toolName,
136					args,
137					options,
138				),
139			);
140		}
141	
142		private async executeToolDirectScoped(
143			agentId: string,
144			userId: string,
145			mcpId: string,
146			toolName: string,
147			args: Record<string, unknown>,
148			options: DirectToolExecutionOptions,
149		): Promise<{
150			content: Array<{ type: string; text: string }>;
151			isError: boolean;
152		}> {
153			const { organizationId } = options;
154			const httpServer = await this.configService.getHttpServer(
155				mcpId,
156				agentId,
157				organizationId,
158			);
159			if (!httpServer) {
160				return {
161					content: [{ type: "text", text: `MCP server '${mcpId}' not found` }],
162					isError: true,
163				};
