 84	/**
 85	 * Drop-in for `auth.api.getSession({ headers })` that resolves on merit.
 86	 *
 87	 * A one-cookie jar takes the original call unchanged; the extra lookups happen
 88	 * only for a jar that is already broken.
 89	 */
 90	export async function resolveSession<A extends SessionReader>(
 91	  auth: A,
 92	  headers: Headers
 93	): Promise<SessionOf<A>> {
 94	  const live = await findLiveProbe(auth, headers);
 95	  if (!live) return await auth.api.getSession({ headers });
 96	  // Resolving on merit must not become "authenticate on anything".
 97	  return (live.session ?? null) as SessionOf<A>;
 98	}
