133	/**
134	 * The jar with its ambiguity already removed, for code that must hand the
135	 * request to a reader that resolves it itself — Better Auth's `/api/auth/*`
136	 * handler. That is where `get-session` lives, the call the web app uses to ask
137	 * whether it is signed in, so leaving it order-dependent would keep the brick
138	 * visible in the UI with every internal call site fixed.
139	 *
140	 * Ordinary jars come back by identity, so the common path does not even copy.
141	 */
142	export async function collapseSessionCookies<A extends SessionReader>(
143	  auth: A,
144	  headers: Headers
145	): Promise<Headers> {
146	  const live = await findLiveProbe(auth, headers);
147	  if (!live) return headers;
148	  if (live.session) return live.headers;
149	
150	  // Nothing verified. Strip the session cookie rather than pass an arbitrary
151	  // dead twin, so sign-in and sign-out on this request cannot act on one.
152	  const companions = nonSessionCookies(headers.get('cookie'));
153	  const stripped = new Headers(headers);
154	  if (companions.length > 0) stripped.set('cookie', companions.join('; '));
155	  else stripped.delete('cookie');
156	  return stripped;
157	}
