649	      }
650	    } catch {
651	      // Session validation failed, continue to anonymous
652	    }
653	
654	    // If the client sent `Authorization: Bearer …` and we got here, it
655	    // wasn't a valid PAT, OAuth access token, or Better Auth session token —
656	    // all three resolution paths above bailed. Return the RFC 6750
657	    // `invalid_token` error (not the generic anonymous fall-through), so
658	    // standards-compliant clients surface "bad token" rather than mistaking
