664	        {
665	          'WWW-Authenticate': bearerChallenge('invalid_token'),
666	        }
667	      );
668	    }
669	
670	    // 3) Anonymous: allow through with null org for discovery (tools/list, initialize)
671	    //    tools/call will enforce org context at the handler level.
672	    if (!requestedOrgId) {
673	      return setContextAndContinue({ organizationId: null, memberRole: null });
