 711	async function resolveMembershipRole(
 712	  env: Env,
 713	  organizationId: string | null,
 714	  userId: string | null
 715	): Promise<string | null> {
 716	  if (!organizationId || !userId) return null;
 717	  const sql = createDbClientFromEnv(env);
 718	  const rows = await sql`
 719	    SELECT role
 720	    FROM "member"
 721	    WHERE "organizationId" = ${organizationId}
 722	      AND "userId" = ${userId}
 723	    LIMIT 1
 724	  `;
 725	  return rows.length > 0 ? ((rows[0].role as string) ?? null) : null;
