 747	async function recoverSessionAuthContext(
 748	  c: Context<{ Bindings: Env }>,
 749	  sessionId: string
 750	): Promise<SessionAuthContext | null> {
 751	  const persisted = await mcpSessionStore.getSession(sessionId);
 752	  if (!persisted) return null;
 753	
 754	  const authCtx = await resolveAuthWithInstructions(c);
 755	
 756	  if (persisted.isAuthenticated) {
 757	    if (!authCtx.isAuthenticated) return null;
 758	    if (persisted.userId && persisted.userId !== authCtx.userId) return null;
 759	    if (persisted.clientId && persisted.clientId !== authCtx.clientId) return null;
 760	  }
 761	
 762	  if (persisted.scopedToOrg !== authCtx.scopedToOrg) {
 763	    return null;
 764	  }
 765	
 766	  if (persisted.scopedToOrg) {
 767	    if (authCtx.organizationId !== persisted.organizationId) {
 768	      return null;
 769	    }
 770	    // Scoped sessions must resolve the caller's membership role too — otherwise
 771	    // role-gated actions deny a legitimate owner/admin over `/mcp/{slug}`.
 772	    await hydrateScopedMemberRole(c.env, authCtx);
 773	  } else {
 774	    authCtx.organizationId = persisted.organizationId;
 775	    authCtx.memberRole = await resolveMembershipRole(
 776	      c.env,
 777	      persisted.organizationId,
 778	      authCtx.userId
 779	    );
 780	
 781	    if (persisted.isAuthenticated && persisted.organizationId && !authCtx.memberRole) {
 782	      return null;
 783	    }
 784	  }
 785	
 786	  // A recovered session cannot move between agents. When the persisted row is
 787	  // unbound, verified request auth may supply one; conflicting bindings fail.
 788	  if (
 789	    authCtx.requestedAgentId &&
 790	    persisted.requestedAgentId &&
 791	    authCtx.requestedAgentId !== persisted.requestedAgentId
 792	  ) {
 793	    return null;
 794	  }
 795	  authCtx.requestedAgentId = persisted.requestedAgentId ?? authCtx.requestedAgentId;
 796	  authCtx.supportsMcpApps = persisted.supportsMcpApps;
 797	  authCtx.instructions = authCtx.organizationId
 798	    ? ((await buildWorkspaceInstructions(authCtx.organizationId)) ?? undefined)
 799	    : undefined;
 800	
 801	  const bindingError = await syncAgentBinding(authCtx);
 802	  if (bindingError) {
 803	    return null;
 804	  }
 805	
 806	  return authCtx;
 807	}
