 995	async function handleAndMaybeConvert(
 996	  transport: WebStandardStreamableHTTPServerTransport,
 997	  req: Request,
 998	  wantsSSE: boolean
 999	): Promise<Response> {
1000	  const rawJson = req.headers.get('x-mcp-format')?.toLowerCase() === 'json';
1001	  const response = await mcpRequestFormat.run({ rawJson }, () => transport.handleRequest(req));
1002	  if (!wantsSSE && response.headers.get('content-type')?.includes('text/event-stream')) {
1003	    return sseToJson(response);
1004	  }
1005	  // Inject SSE heartbeat pings to keep the stream alive through proxies.
1006	  // Thread the inbound request's AbortSignal so abnormal disconnects clear
1007	  // the interval (same root cause as PR #833/#845).
1008	  return withSSEHeartbeat(response, req.signal);
1009	}
