1015	async function resolveAuthWithInstructions(
1016	  c: Context<{ Bindings: Env }>,
1017	  req?: Request
1018	): Promise<SessionAuthContext> {
1019	  const authCtx: SessionAuthContext = extractAuthContext(c);
1020	  const request = req ?? c.req.raw;
1021	  // `baseUrl` stays as extractAuthContext set it: empty means "no configured
1022	  // public origin", which is what makes `getPublicWebUrl` fall back to the
1023	  // hosted UI for backend-only self-hosters. Forcing the request origin here
1024	  // would point every MCP link at a host that serves no frontend.
1025	  authCtx.requestUrl = publicMcpRequestUrl(request);
1026	  if (req) {
1027	    const initialize = await readInitializeRequest(req);
1028	    // Verified worker auth already supplies an agent. Only fall back to the
1029	    // initialize metadata used by ordinary MCP clients when auth has none.
1030	    authCtx.requestedAgentId = authCtx.requestedAgentId ?? initialize?.requestedAgentId ?? null;
1031	  }
1032	  if (authCtx.organizationId) {
1033	    authCtx.instructions = (await buildWorkspaceInstructions(authCtx.organizationId)) ?? undefined;
1034	  }
1035	  return authCtx;
1036	}
