1038	async function syncAgentBinding(authCtx: SessionAuthContext): Promise<string | null> {
1039	  const requestedAgentId = authCtx.requestedAgentId?.trim() || null;
1040	  authCtx.agentId = null;
1041	
1042	  if (!requestedAgentId) return null;
1043	  if (!isValidAgentId(requestedAgentId)) {
1044	    return 'agentId must be 3-60 lowercase alphanumeric chars with hyphens, starting with a letter';
1045	  }
1046	  if (!authCtx.isAuthenticated) {
1047	    return 'Authentication required to bind MCP sessions to an agent.';
1048	  }
1049	  if (!authCtx.organizationId) {
1050	    return null;
1051	  }
1052	
1053	  const exists = await agentExistsInOrganization(authCtx.organizationId, requestedAgentId);
1054	  if (!exists) {
1055	    return `Agent '${requestedAgentId}' was not found in the current organization.`;
1056	  }
1057	
1058	  authCtx.agentId = requestedAgentId;
1059	  await touchAgentLastUsed(authCtx.organizationId, requestedAgentId);
1060	  return null;
1061	}
