1063	function createSessionTransport(
1064	  env: Env,
1065	  authCtx: SessionAuthContext,
1066	  sessionIdGenerator: () => string
1067	): { transport: WebStandardStreamableHTTPServerTransport; server: Server } {
1068	  const transport = new WebStandardStreamableHTTPServerTransport({
1069	    sessionIdGenerator,
1070	    onsessioninitialized: (id) => {
1071	      // The per-session authCtx object is shared by every request on this
1072	      // session, so stamping once here threads the session id into each
1073	      // tool call's ToolContext (audit rows group client activity by it).
1074	      authCtx.mcpSessionId = id;
1075	      sessions.set(id, {
1076	        transport,
1077	        server,
1078	        authCtx,
1079	        lastAccessedAt: Date.now(),
1080	      });
1081	    },
1082	  });
1083	  transport.onclose = () => {
1084	    if (transport.sessionId) {
1085	      sessions.delete(transport.sessionId);
1086	      void deletePersistedSession(transport.sessionId);
1087	    }
1088	  };
1089	  const server = createServerForContext(env, authCtx, authCtx.supportsMcpApps ?? false);
1090	  return { transport, server };
1091	}
