 10	const JSON_MCP_ACCEPT = "application/json";
 11	
 12	function uniqueStrings(values: string[]): string[] {
 13	  const seen = new Set<string>();
 14	  const result: string[] = [];
 15	  for (const value of values) {
 16	    if (seen.has(value)) continue;
 17	    seen.add(value);
 18	    result.push(value);
 19	  }
 20	  return result;
 21	}
 22	
 23	function getMcpUrlCandidates(rawUrl: string): string[] {
 24	  let parsed: URL;
 25	  try {
 26	    parsed = new URL(rawUrl);
 27	  } catch {
 28	    return [rawUrl];
 29	  }
 30	
 31	  const candidates = [parsed.toString()];
 32	  const hostname = parsed.hostname.toLowerCase();
 33	  if (hostname === "localhost" || hostname === "::1" || hostname === "[::1]") {
 34	    const ipv4 = new URL(parsed.toString());
 35	    ipv4.hostname = "127.0.0.1";
 36	    candidates.push(ipv4.toString());
 37	
 38	    const dockerHost = new URL(parsed.toString());
 39	    dockerHost.hostname = "host.docker.internal";
 40	    candidates.push(dockerHost.toString());
 41	  }
 42	
 43	  return uniqueStrings(candidates);
 44	}
 45	
 46	function formatNetworkErrorMessage(
 47	  error: unknown,
 48	  triedUrls: string[]
 49	): string {
 50	  const baseMessage = error instanceof Error ? error.message : String(error);
 51	  return `MCP fetch failed (${baseMessage}). Tried: ${triedUrls.join(", ")}`;
 52	}
 53	
 54	async function fetchMcpWithFallback(
 55	  mcpUrl: string,
 56	  init: RequestInit
 57	): Promise<{ response: Response; usedUrl: string }> {
 58	  const candidates = getMcpUrlCandidates(mcpUrl);
 59	  let lastError: unknown = null;
 60	
 61	  for (const candidate of candidates) {
 62	    try {
 63	      const response = await fetch(candidate, init);
 64	      return { response, usedUrl: candidate };
 65	    } catch (error) {
 66	      lastError = error;
 67	    }
 68	  }
 69	
 70	  throw new Error(formatNetworkErrorMessage(lastError, candidates));
 71	}
