 73	type JsonRpcError = { message: string; code: number };
 74	type JsonRpcResponse<T = unknown> = {
 75	  result?: T;
 76	  error?: JsonRpcError;
 77	};
 78	
 79	/**
 80	 * Resolve the MCP endpoint URL.
 81	 * Priority: explicit config > LOBU_MEMORY_URL env > saved memory server > default cloud server.
 82	 */
 83	export async function resolveMcpEndpoint(config?: {
 84	  mcpUrl?: unknown;
 85	  url?: unknown;
 86	  apiUrl?: unknown;
 87	}): Promise<string | null> {
 88	  // Explicit config should win over ambient auth/session state so callers can
 89	  // deterministically target a specific server.
 90	  if (config) {
 91	    if (typeof config.mcpUrl === "string" && config.mcpUrl.trim().length > 0) {
 92	      return config.mcpUrl;
 93	    }
 94	    if (typeof config.url === "string" && config.url.trim().length > 0) {
 95	      const url = config.url as string;
 96	      return url.includes("/mcp") ? url : `${url.replace(/\/+$/, "")}/mcp`;
 97	    }
 98	    if (typeof config.apiUrl === "string" && config.apiUrl.trim().length > 0) {
 99	      return `${(config.apiUrl as string).replace(/\/+$/, "")}/mcp`;
100	    }
101	  }
102	
103	  // Fall back to auth store / env when no explicit target was provided.
104	  return resolveServerUrl();
105	}
