107	async function mcpFetch(
108	  mcpUrl: string,
109	  body: Record<string, unknown>,
110	  sessionId?: string,
111	  protocolVersion?: string,
112	  contextName?: string
113	): Promise<{ data: JsonRpcResponse; usedUrl: string; response: Response }> {
114	  const headers: Record<string, string> = {
115	    "Content-Type": "application/json",
116	  };
117	  const tokenResult = await getUsableToken(mcpUrl, contextName);
118	  if (tokenResult) {
119	    headers.Authorization = `Bearer ${tokenResult.token}`;
120	  }
121	  headers.Accept = JSON_MCP_ACCEPT;
122	  if (sessionId) {
123	    headers["mcp-session-id"] = sessionId;
124	    headers["MCP-Protocol-Version"] = protocolVersion ?? MCP_PROTOCOL_VERSION;
125	  }
126	
127	  const { response: res, usedUrl } = await fetchMcpWithFallback(mcpUrl, {
128	    method: "POST",
129	    headers,
130	    body: JSON.stringify(body),
131	  });
132	
133	  if (!res.ok) {
134	    const authContext = tokenResult
135	      ? ` using context "${tokenResult.contextName}"`
136	      : " without an access token";
137	    const hint =
138	      res.status === 401
139	        ? `${authContext}. Try --context <name> or run \`lobu context use <name>\`.`
140	        : authContext;
141	    throw new ApiError(
142	      `MCP request failed via ${usedUrl}: ${res.status} ${res.statusText}${hint}`,
143	      res.status
144	    );
145	  }
146	
147	  const raw = await res.text();
148	  const data = raw.length > 0 ? (JSON.parse(raw) as JsonRpcResponse) : {};
149	  return { data, usedUrl, response: res };
150	}
