152	async function initializeMcpSession(
153	  mcpUrl: string,
154	  contextName?: string
155	): Promise<{ sessionId: string; protocolVersion: string; usedUrl: string }> {
156	  const { data, usedUrl, response } = await mcpFetch(
157	    mcpUrl,
158	    {
159	      jsonrpc: "2.0",
160	      id: "__init__",
161	      method: "initialize",
162	      params: {
163	        protocolVersion: MCP_PROTOCOL_VERSION,
164	        capabilities: {},
165	        clientInfo: { name: "lobu-memory", version: "1.0.0" },
166	      },
167	    },
168	    undefined,
169	    undefined,
170	    contextName
171	  );
172	
173	  if (data.error) {
174	    throw new ApiError(
175	      `MCP error: ${data.error.message} (code ${data.error.code})`
176	    );
177	  }
178	
179	  const sessionId = response.headers.get("mcp-session-id");
180	  if (!sessionId) {
181	    throw new ApiError(
182	      `MCP initialize via ${usedUrl} did not return an mcp-session-id header`
183	    );
184	  }
185	
186	  const protocolVersion = (
187	    data.result as { protocolVersion?: unknown } | undefined
188	  )?.protocolVersion;
189	  if (typeof protocolVersion !== "string" || protocolVersion.length === 0) {
190	    throw new ApiError(
191	      `MCP initialize via ${usedUrl} did not return a protocolVersion`
192	    );
193	  }
194	
195	  await mcpFetch(
196	    mcpUrl,
197	    {
198	      jsonrpc: "2.0",
199	      method: "notifications/initialized",
200	    },
201	    sessionId,
202	    protocolVersion,
203	    contextName
204	  );
205	
206	  return { sessionId, protocolVersion, usedUrl };
207	}
