209	export async function mcpRpc(
210	  mcpUrl: string,
211	  method: string,
212	  params?: Record<string, unknown>,
213	  contextName?: string
214	) {
215	  const { sessionId, protocolVersion } = await initializeMcpSession(
216	    mcpUrl,
217	    contextName
218	  );
219	  const { data } = await mcpFetch(
220	    mcpUrl,
221	    {
222	      jsonrpc: "2.0",
223	      id: 1,
224	      method,
225	      params: params || {},
226	    },
227	    sessionId,
228	    protocolVersion,
229	    contextName
230	  );
231	
232	  if (data.error) {
233	    throw new ApiError(
234	      `MCP error: ${data.error.message} (code ${data.error.code})`
235	    );
236	  }
237	
238	  return data.result;
239	}
