241	/**
242	 * Shared REST-proxy call against `{origin}/api/{orgSlug}/{path}`, reusing the
243	 * same auth resolution and localhost/docker-host fallback as `mcpRpc`. Returns
244	 * the raw handler result as parsed JSON (no MCP envelope). Throws `ApiError` on
245	 * non-2xx, surfacing the server's `{ error }` message when present.
246	 *
247	 * `restToolCall` (POST) and `restGet` (GET) are thin wrappers — they differ only
248	 * in HTTP method/body and the labels used in the no-org and failure messages.
249	 */
250	async function restCall<T>(
251	  mcpUrl: string,
252	  path: string,
253	  opts: {
254	    method: "GET" | "POST";
255	    body?: Record<string, unknown>;
256	    failureLabel: string;
257	    noOrgMessage: (mcpUrl: string) => string;
258	  },
259	  contextName?: string
260	): Promise<T> {
261	  const headers: Record<string, string> = {};
262	  if (opts.body !== undefined) headers["Content-Type"] = "application/json";
263	  const tokenResult = await getUsableToken(mcpUrl, contextName);
264	  if (tokenResult) {
265	    headers.Authorization = `Bearer ${tokenResult.token}`;
266	  }
267	
268	  // Prefer the org slug pinned in the URL (`/mcp/{slug}`). Fall back to the
269	  // session's bound org so callers using a bare `/mcp` URL still resolve.
270	  const orgSlug = orgFromMcpUrl(mcpUrl) ?? tokenResult?.session.org ?? null;
271	  if (!orgSlug) {
272	    throw new ApiError(opts.noOrgMessage(mcpUrl));
273	  }
274	
275	  const baseUrl = new URL(mcpUrl).origin;
276	  const endpoint = `${baseUrl}/api/${orgSlug}/${path}`;
277	
278	  const { response: res, usedUrl } = await fetchMcpWithFallback(endpoint, {
279	    method: opts.method,
280	    headers,
281	    ...(opts.body !== undefined ? { body: JSON.stringify(opts.body) } : {}),
282	  });
283	
284	  const raw = await res.text();
285	  if (!res.ok) {
286	    let message = `${res.status} ${res.statusText}`;
287	    if (raw) {
288	      try {
289	        message = extractApiError(
290	          JSON.parse(raw),
291	          res.status,
292	          res.statusText
293	        ).message;
294	      } catch {
295	        message = raw;
296	      }
297	    }
298	    const authContext = tokenResult
299	      ? ` using context "${tokenResult.contextName}"`
300	      : " without an access token";
301	    const hint =
302	      res.status === 401
303	        ? `${authContext}. Try --context <name> or run \`lobu context use <name>\`.`
304	        : authContext;
305	    throw new ApiError(
306	      `${opts.failureLabel} failed via ${usedUrl}: ${message}${hint}`,
307	      res.status
308	    );
309	  }
310	
311	  return (raw.length > 0 ? JSON.parse(raw) : {}) as T;
312	}
