128	/**
129	 * Resolve a usable bearer token from top-level `lobu login` credentials.
130	 */
131	export async function getUsableToken(
132	  mcpUrl?: string,
133	  contextName?: string
134	): Promise<{
135	  token: string;
136	  session: MemorySession;
137	  contextName: string;
138	} | null> {
139	  let target = await resolveContext(contextName);
140	  const resolvedUrl = mcpUrl
141	    ? normalizeMcpUrl(mcpUrl)
142	    : await resolveServerUrl(undefined, target.name);
143	
144	  if (mcpUrl && !contextName) {
145	    const requestedBase = baseMcpUrl(resolvedUrl);
146	    const currentContextUrl = await resolveServerUrl(undefined, target.name);
147	    const currentContextBase = baseMcpUrl(currentContextUrl);
148	
149	    // Keep the active context when it already targets the requested memory
150	    // server. Multiple contexts can legitimately share the default memory URL,
151	    // and blindly picking the first matching context can select credentials for
152	    // an unrelated context (or one with no login), causing unauthenticated MCP
153	    // requests.
154	    if (currentContextBase !== requestedBase) {
155	      const matched = await findContextByMemoryUrl(resolvedUrl);
156	      if (matched) target = matched;
157	    }
158	  }
159	
160	  if (mcpUrl && !process.env.LOBU_API_TOKEN) {
161	    const contextUrl = await resolveServerUrl(undefined, target.name);
162	    const requestedBase = baseMcpUrl(resolvedUrl);
163	    const contextBase = baseMcpUrl(contextUrl);
164	    if (requestedBase !== contextBase) {
165	      throw new Error(
166	        `Refusing to send stored context credentials for "${target.name}" to ${requestedBase}. Configure that context's memory URL or set LOBU_API_TOKEN explicitly.`
167	      );
168	    }
169	  }
170	
171	  const token = await getToken(target.name);
172	  if (!token) return null;
173	
174	  const org =
175	    orgFromMcpUrl(resolvedUrl) ??
176	    (await resolveOrg(undefined, undefined, target.name));
177	  const sessionUrl =
178	    org && !orgFromMcpUrl(resolvedUrl)
179	      ? mcpUrlForOrg(resolvedUrl, org)
180	      : resolvedUrl;
181	
182	  return {
183	    token,
184	    contextName: target.name,
185	    session: {
186	      mcpUrl: sessionUrl,
187	      org,
188	      tokenType: "Bearer",
189	      updatedAt: new Date().toISOString(),
190	    },
191	  };
192	}
