188	// REST mutation factory — for hooks that hit REST verbs (POST/PATCH/DELETE) on
189	// path-scoped endpoints via fetchWithTimeout + throwIfNotOk, rather than the
190	// tool-style `apiCall`. The returned hook takes the same hook-level args the
191	// original did (e.g. an agentId); `url` and `invalidate` receive the resolved
192	// slug plus those args. `body` is omitted for no-body verbs (DELETE). `read`
193	// controls response parsing: 'json' (default), 'none' (void), or a custom
194	// reader for non-standard envelopes.
195	// ---------------------------------------------------------------------------
196	
197	export function createRestMutation<
198	  THookArgs extends readonly unknown[],
199	  TParams = void,
200	  TResult = unknown,
201	>(config: {
202	  method: 'POST' | 'PATCH' | 'PUT' | 'DELETE';
203	  // `url` gets the resolved slug, the mutate params (some endpoints put an id
204	  // from params in the path), and the hook-level args (e.g. agentId). `invalidate`
205	  // gets slug + args. Object form so call sites destructure only what they use.
206	  url: (ctx: { slug: string; params: TParams; args: THookArgs }) => string;
207	  body?: (params: TParams) => unknown;
208	  read?: 'json' | 'none' | ((res: Response) => Promise<TResult>);
209	  invalidate: (ctx: { slug: string | null; args: THookArgs }) => unknown[][];
210	  successMessage?: string;
211	  errorMessage: string;
212	}) {
213	  return (...hookArgs: THookArgs) => {
214	    const { slug } = getPathScope();
215	    const queryClient = useQueryClient();
216	    return useMutation({
217	      mutationFn: async (params: TParams): Promise<TResult> => {
218	        const init: RequestInit = { method: config.method, credentials: 'include' };
219	        if (config.body) {
220	          init.headers = { 'Content-Type': 'application/json' };
221	          init.body = JSON.stringify(config.body(params));
222	        }
223	        const res = await fetchWithTimeout(
224	          config.url({ slug: slug as string, params, args: hookArgs }),
225	          init
226	        );
227	        if (!res.ok) {
228	          throw await apiErrorFor(res);
229	        }
230	        const read = config.read ?? 'json';
231	        if (read === 'none') return undefined as TResult;
232	        if (read === 'json') return (await res.json()) as TResult;
233	        return read(res);
234	      },
235	      onSuccess: () => {
236	        for (const key of config.invalidate({ slug, args: hookArgs })) {
237	          queryClient.invalidateQueries({ queryKey: key });
238	        }
239	        if (config.successMessage) {
240	          toast.success(config.successMessage);
241	        }
242	      },
243	      onError: (error: Error) => {
244	        toast.error(error.message || config.errorMessage);
245	      },
180	    if (!response.ok) {
181	      captureApiError(input, response, init);
182	    }
183	    return response;
184	  } catch (error) {
185	    // Timeout-driven aborts are expected — don't report them.
186	    const isAbort =
187	      timeoutController.signal.aborted ||
188	      init?.signal?.aborted === true ||
189	      (error instanceof DOMException && error.name === 'AbortError') ||
190	      (error instanceof Error && error.name === 'AbortError');
191	    if (!isAbort) {
192	      captureApiException(input, error, init);
193	    }
194	    throw error;
195	  } finally {
196	    clearTimeout(timeout);
197	  }
198	}
