    91	/**
    92	 * Atomically fetch and delete the pending invocation. The PG-backed
    93	 * `pending-tool` row uses DELETE ... RETURNING so the first click claims
    94	 * the payload and subsequent webhook retries see null and no-op.
    95	 */
    96	async function takePendingToolInvocation(
    97		requestId: string,
    98	): Promise<PendingToolInvocation | null> {
