   117	function actionEventTeamId(
   118		event: any,
   119		connection: PlatformConnection,
   120	): string | null {
   121		const raw = event?.raw as Record<string, any> | undefined;
   122		const teamId =
   123			event?.teamId ??
   124			raw?.team_id ??
   125			raw?.team?.id ??
   126			event?.user?.teamId ??
   127			event?.user?.team_id ??
   128			connection.metadata?.teamId ??
   129			(connection.settings?.previewMode === true ? "" : undefined);
   130		return typeof teamId === "string" ? teamId : null;
