   132	
   133	/**
   134	 * Map the clicking Slack user to a Lobu member allowed to decide this run:
   135	 * exactly ONE workspace-scoped Slack identity for (team, platform user) that
   136	 * joins to an org member, AND that member is an admin/owner OR the run's recorded field
   137	 * owner (`ownerUserId`). A non-admin member who is not the owner resolves null,
   138	 * same as an unverified account.
   139	 */
   140	async function resolveSlackActionReviewer(params: {
   141		connection: PlatformConnection;
   142		platformUserId: string | undefined;
   143		teamId: string | null;
   144		ownerUserId?: string | null;
   145	}): Promise<{ userId: string; role: string } | null> {
   146		const { connection, platformUserId, teamId, ownerUserId } = params;
   147		if (connection.platform !== "slack") return null;
   148		if (!connection.organizationId || !platformUserId || teamId == null)
   149			return null;
   150		const userId = await resolveChatUserIdentity("slack", teamId, platformUserId);
   151		if (!userId) return null;
   152		const sql = getDb();
   153		const rows = await sql<{ role: string }>`
   154	    SELECT m.role
   155	    FROM "member" m
   156	    WHERE m."userId" = ${userId}
   157	      AND m."organizationId" = ${connection.organizationId}
   158	    LIMIT 2
   159	  `;
   160		if (rows.length !== 1) return null;
   161		const { role } = rows[0];
   162		const isAdmin = role === "admin" || role === "owner";
   163		const isOwner = ownerUserId != null && userId === ownerUserId;
   164		if (!isAdmin && !isOwner) return null;
   165		return { userId, role };
   166	}
   167	
   168	async function resolveEntityApprovalRun(
   169		runId: number,
   170		organizationId: string,
   171	): Promise<{
   172		state: "pending" | "approved" | "rejected" | "not_found";
   173		/** action_input.owner_user_id — the field owner allowed to decide this run. */
   174		ownerUserId: string | null;
   175	}> {
   176		const actionKeys = pgTextArray([...ENTITY_CHANGE_ACTION_KEYS]);
   177		const rows = await getDb()<{
   178			id: number;
   179			approval_status: string | null;
   180			owner_user_id: string | null;
   181		}>`
   182	    SELECT id, approval_status, action_input->>'owner_user_id' AS owner_user_id
   183	    FROM runs
   184	    WHERE id = ${runId}
   185	      AND organization_id = ${organizationId}
   186	      AND run_type = 'internal'
   187	      AND action_key = ANY(${actionKeys}::text[])
   188	    LIMIT 1
   189	  `;
   190		if (rows.length !== 1) return { state: "not_found", ownerUserId: null };
   191		const status = rows[0].approval_status;
   192		const state =
   193			status === "pending" || status === "approved" || status === "rejected"
   194				? status
   195				: "not_found";
   196		return { state, ownerUserId: rows[0].owner_user_id ?? null };
   197	}
   198	
   199	/**
   200	 * Replace the approval card's buttons with a plain-text decision summary.
   201	 * Best-effort: silently swallows edit failures (the card may be unreachable
   202	 * after a long gap, or the platform may not support edits).
   203	 */
   204	async function stripApprovalButtons(
   205	  sent: SentMessage | undefined,
   206	  pending: {
   207	    mcpId: string;
   208	    toolName: string;
   209	    args: Record<string, unknown>;
   210	  },
   211		decision: string,
   212	): Promise<void> {
   213	  if (!sent) return;
   214	  const summary =
   215	    `*Tool Approval*\n${pending.mcpId} → ${pending.toolName}\n` +
   216	    `${formatToolArgs(pending.args)}\n\n_${describeDecision(decision)}_`;
   217	  try {
   218	    await sent.edit(summary);
   219	  } catch {
   220	    // best effort — card may be stale, edit may be unsupported
   221	  }
   222	}
   223	
   224	function formatToolArgs(args: Record<string, unknown>): string {
   225	  return Object.entries(args)
   226	    .map(([k, v]) => {
   227	      const val = typeof v === "string" ? v : JSON.stringify(v);
   228	      return `  ${k}: ${val}`;
   229	    })
   230	    .join("\n");
   231	}
   232	
   233	/** Context tracked per posted question so the click handler can feed the
   234	 *  clicked value back into the worker with the same routing as the original
   235	 *  message (userId/conversationId/channelId/teamId). Also holds the SentMessage
   236	 *  for the card so buttons can be stripped after a click. */
   237	interface PendingQuestionEntry {
   238	  question: PostedQuestion;
   239	  sent?: SentMessage;
   240	}
   241	
   242	export function registerInteractionBridge(
   243	  interactionService: InteractionService,
   244	  manager: ChatInstanceManager,
   245	  connection: PlatformConnection,
   246	  chat: any,
   247	  grantStore?: GrantStore,
   248		executeToolDirect?: ExecuteToolDirectFn,
   249	): () => void {
   250	  const { id: connectionId, platform } = connection;
   251	
   252	  // Per-connection state (avoids cross-contamination between connections)
   253	  const handledEvents = new Set<string>();
   254	  const activeTimers = new Set<NodeJS.Timeout>();
   255	  // Slack retries event_callback webhooks at ~1s/2s/5s/30s/60s/3min on
   256	  // missed acks; a 30s dedup window let late retries through and
   257	  // double-processed the event. 5min covers the full retry envelope.
   258	  const HANDLED_EVENT_TTL_MS = 5 * 60_000;
   259	  function markHandled(id: string): void {
   260	    handledEvents.add(id);
   261	    const timer = setTimeout(() => {
   262	      handledEvents.delete(id);
   263	      activeTimers.delete(timer);
   264	    }, HANDLED_EVENT_TTL_MS);
   265	    activeTimers.add(timer);
   266	  }
   267	
   268	  // Tracks posted tool-approval cards so we can edit them on click to strip
   269	  // the buttons. Keyed by requestId (== PostedToolApproval.id == pending-tool
   270	  // store key). Auto-expire window matches the pending-tool TTL (24h) so a
   271	  // late click can still find the card to strip.
   272	  const APPROVAL_CARD_TTL_MS = 24 * 60 * 60 * 1000;
   273	  const pendingApprovalCards = new Map<string, SentMessage>();
   274	  const pendingApprovalTimers = new Map<string, NodeJS.Timeout>();
   275	  function trackApprovalCard(requestId: string, sent: SentMessage): void {
   276	    pendingApprovalCards.set(requestId, sent);
   277	    const timer = setTimeout(() => {
   278	      pendingApprovalCards.delete(requestId);
   279	      pendingApprovalTimers.delete(requestId);
   280	    }, APPROVAL_CARD_TTL_MS);
   281	    pendingApprovalTimers.set(requestId, timer);
   282	  }
   283	  function claimApprovalCard(requestId: string): SentMessage | undefined {
   284	    const sent = pendingApprovalCards.get(requestId);
   285	    pendingApprovalCards.delete(requestId);
   286	    const timer = pendingApprovalTimers.get(requestId);
   287	    if (timer) {
   288	      clearTimeout(timer);
   289	      pendingApprovalTimers.delete(requestId);
   290	    }
   291	    return sent;
   292	  }
   293	
   294	  // Pending questions are persisted in `public.pending_interactions` so a
   295	  // click landing on a different pod can still claim the entry. The local
   296	  // `pendingSentMessages` map holds the non-serializable platform
   297	  // `SentMessage` (used to strip card buttons on click) — losing it
   298	  // cross-pod is best-effort UX, not correctness.
   299	  //
   300	  // DB-row sweeping is owned globally by `coreServices.sweepEphemeralTables`
   300	  // DB-row sweeping is owned globally by `coreServices.sweepEphemeralTables`
   301	  // (scheduled every 5 minutes in `packages/server/src/scheduled/jobs.ts`).
   302	  // We do NOT call `sweepStalePendingInteractions` per-bridge — N bridges
   303	  // hitting the same table N times is wasted work. The local sweep below
   304	  // is in-memory only: it evicts cache entries past their TTL so the Map
   305	  // doesn't grow unbounded for questions that are never clicked.
   306	  const PENDING_SENT_TTL_MS = 24 * 60 * 60 * 1000;
   307	  const PENDING_SENT_SWEEP_INTERVAL_MS = 60 * 60 * 1000;
   308	  interface CachedSent {
   309	    sent: SentMessage;
   310	    registeredAt: number;
   311	  }
   312	  const pendingSentMessages = new Map<string, CachedSent>();
   313	  const pendingSentSweepTimer = setInterval(() => {
   314	    const ttlCutoff = Date.now() - PENDING_SENT_TTL_MS;
   315	    for (const [id, entry] of pendingSentMessages) {
   316	      if (entry.registeredAt <= ttlCutoff) {
   317	        pendingSentMessages.delete(id);
   318	      }
   319	    }
   320	  }, PENDING_SENT_SWEEP_INTERVAL_MS);
   321	  pendingSentSweepTimer.unref?.();
   322	  /**
   323	   * Persist a pending question row, then cache its SentMessage handle so a
   324	   * click on this pod can edit the card. The persist happens first — see
   325	   * `onQuestionCreated` for the post-then-persist policy that wraps the
   326	   * card-post; this function is invoked only after the row is durable.
   327	   */
   328	  function rememberSentMessage(
   329	    questionId: string,
   330			sent: SentMessage | undefined,
   331	  ): void {
   332	    if (!sent) return;
   333	    pendingSentMessages.set(questionId, {
   334	      sent,
   335	      registeredAt: Date.now(),
   336	    });
   337	  }
   338	  async function claimQuestion(
   339	    questionId: string,
   340	    organizationId: string,
   341			expectedUserId: string,
   342	  ): Promise<PendingQuestionEntry | undefined> {
   343	    const stored = await claimPendingQuestion(
   344	      questionId,
   345	      organizationId,
   346	      connectionId,
   347				expectedUserId,
   348	    ).catch((error) => {
   349	      logger.error(
   350	        { connectionId, questionId, error: String(error) },
   351					"Failed to claim pending question",
   352	      );
   353	      return null;
   354	    });
   355	    if (!stored) return undefined;
   356	    const cached = pendingSentMessages.get(questionId);
   357	    pendingSentMessages.delete(questionId);
   358	    return { question: stored.question, sent: cached?.sent };
   359	  }
   360	
   361	  /**
   362	   * Shared preamble for every InteractionService handler: platform/tenant
   363	   * guard, per-connection dedup (Slack retries the same webhook for up to
   364	   * 5min), thread resolution, and a catch-all so one handler's failure never
   365	   * escapes into the event emitter. `handler` runs only once per event id with
   366	   * a resolved thread; org/user sub-checks stay inline in each body.
   367	   */
   368	  function withResolvedThread<
   369	    E extends {
   370	      id: string;
   371	      channelId: string;
   372	      conversationId: string;
   373	      platform?: string;
   374	    },
   375	  >(
   376	    eventName: string,
   377	    handler: (event: E, thread: any) => Promise<void>,
   378	  ): (event: E) => Promise<void> {
   379	    return async (event: E) => {
   380	      try {
   381	        if (!shouldHandle(event, platform, connectionId, manager)) return;
   382	        if (handledEvents.has(event.id)) return;
   383	        markHandled(event.id);
   384	
   385	        const thread = await resolveThread(
   386	          manager,
   387	          connectionId,
   388	          event.channelId,
   389	          event.conversationId,
   390	        );
   391	        if (!thread) return;
   392	
   393	        await handler(event, thread);
   394	      } catch (error) {
   395	        logger.error(
   396	          { connectionId, error: String(error) },
   397	          `Unhandled error in ${eventName} handler`,
   398	        );
   399	      }
   400	    };
   401	  }
   402	
   403	  const onQuestionCreated = withResolvedThread<PostedQuestion>(
   404	    "question:created",
   405	    async (event, thread) => {
   406	      // Cross-tenant scoping: every pending row must carry the bridge's
   407	      // org. Without a known org we can't safely persist or claim, so
   408	      // drop the event rather than write an un-scoped row.
   409	      const organizationId = connection.organizationId;
   410	      if (!organizationId) {
   411	        logger.warn(
   412	          { connectionId, questionId: event.id },
   413						"Skipping question:created — connection has no organizationId",
   414	        );
   415	        return;
   416	      }
   417	      if (!event.userId) {
   418	        logger.warn(
   419	          { connectionId, questionId: event.id },
   420						"Skipping question:created — event has no userId",
   421	        );
   422	        return;
   423	      }
   424	
   425	      // Persist the pending row BEFORE posting the card. If the persist
   426	      // fails we never show buttons that would no-op on click. If the row
   427	      // is written but the post fails, we delete it on the way out so a
   428	      // stale row doesn't sit waiting for a click that will never arrive.
   429	      try {
   430	        await storePendingQuestion(
   431	          event.id,
   432	          organizationId,
   433	          connectionId,
   434	          event.userId,
   435						{ question: event },
   436	        );
   437	      } catch (error) {
   438	        logger.error(
   439	          { connectionId, questionId: event.id, error: String(error) },
   440						"Failed to persist pending question — not posting card",
   441	        );
   442	        return;
   443	      }
   444	
   445	      const buttons = event.options.map((option, i) =>
   446	        Button({
   447	          id: `question:${event.id}:${i}`,
   448	          label: option,
   449	          value: option,
   450					}),
   451	      );
   452	      const card = Card({
   453	        children: [CardText(event.question), Actions(buttons)],
   454	      });
   455	      const fallbackText = `${event.question}\n${event.options.map((o, i) => `${i + 1}. ${o}`).join("\n")}`;
   456	      const sent = await postWithFallback(
   457	        thread,
   458	        { card, fallbackText },
   459	        connectionId,
   460					"question interaction",
   461	      );
   462	      if (!sent) {
   463	        // Post failed entirely. The row exists but no card was rendered,
   464	        // so a click can never come — DELETE the row to keep the table
   465	        // clean. Pre-fix used `claimPendingQuestion` (UPDATE setting
   466	        // claimed_at), which leaves a phantom row sitting around with
   467	        // claimed_at set until the 24h sweep. Hard-delete is the
   468	        // semantically correct end state, and the four-field scoping
   469	        // matches the claim path's safety invariant: a leaked id alone
   470	        // cannot delete another tenant's row.
   471	        try {
   472	          await deletePendingQuestion(
   473	            event.id,
   474	            organizationId,
   475	            connectionId,
   476							event.userId,
   477	          );
   478	        } catch (error) {
   479	          logger.debug(
   480	            { connectionId, questionId: event.id, error: String(error) },
   481							"Failed to drop pending row after post failure",
   482	          );
   483	        }
   484	        return;
   485	      }
   486	      rememberSentMessage(event.id, sent);
   487	    },
   488	  );
   489	
   490	  const onToolApprovalNeeded = withResolvedThread<PostedToolApproval>(
   491	    "tool:approval-needed",
   492	    async (event, thread) => {
   493	      const argsText = formatToolArgs(event.args);
   494	      const text = `Tool Approval\n${event.mcpId} → ${event.toolName}\n${argsText}`;
   495	      const tid = event.id;
   496	
   497	      const card = Card({
   498	        children: [
   499	          CardText(
   500							`*Tool Approval*\n${event.mcpId} → ${event.toolName}\n${argsText}`,
   501	          ),
   502	          Actions([
   503	            Button({
   504	              id: `tool:${tid}:1h`,
   505	              label: "Allow 1h",
   506	              style: "primary",
   507	              value: "1h",
   508	            }),
   509	            Button({
   510	              id: `tool:${tid}:24h`,
   511	              label: "Allow 24h",
   512	              style: "primary",
   513	              value: "24h",
   514	            }),
   515	            Button({
   516	              id: `tool:${tid}:always`,
   517	              label: "Allow always",
   518	              style: "primary",
   519	              value: "always",
   520	            }),
   521	            Button({
   522	              id: `tool:${tid}:deny`,
   523	              label: "Deny always",
   524	              style: "danger",
   525	              value: "deny",
   526	            }),
   527	          ]),
   528	        ],
   529	      });
   530	      const sent = await postWithFallback(
   531	        thread,
   532	        { card, fallbackText: text },
   533	        connectionId,
   534					"tool approval interaction",
   535	      );
   536	      if (sent) {
   537	        trackApprovalCard(tid, sent);
   538	      }
   539	    },
   540	  );
   541	
   542	  const onLinkButtonCreated = withResolvedThread<PostedLinkButton>(
   543	    "link-button:created",
   544	    async (event, thread) => {
   545	      const linkButton = LinkButton({
   546	        url: event.url,
   547	        label: event.label,
   548	      });
   549	      // The button itself carries the label — only render an extra line of
   550	      // card-body text when the caller supplied a distinct `body` explaining
   551	      // *why* (e.g. for OAuth, "Authorize {mcp} to continue."). Falling back
   552	      // to `label` again would produce the "Connect sentry / [Connect sentry]"
   553	      // duplication we saw in Slack.
   554	      const bodyText = event.body?.trim();
   555	      const cardChildren =
   556	        bodyText && bodyText !== event.label
   557	          ? [CardText(bodyText), Actions([linkButton])]
   558	          : [Actions([linkButton])];
   559	      const card = Card({ children: cardChildren });
   560	      const fallbackText = bodyText
   561	        ? `${bodyText} ${event.label}: ${event.url}`
   562	        : `${event.label}: ${event.url}`;
   563	      await postWithFallback(
   564	        thread,
   565	        { card, fallbackText },
   566	        connectionId,
   567					"link button interaction",
   568	      );
   569	    },
   570	  );
   571	
   572	  const onSuggestionCreated = withResolvedThread<PostedSuggestion>(
   573	    "suggestion:created",
   574	    async (event, thread) => {
   575	      if (event.prompts.length === 0) return;
   576	      const organizationId = connection.organizationId;
   577	      if (!organizationId) {
   578	        logger.warn(
   579	          { connectionId, suggestionId: event.id },
   580	          "Skipping suggestion:created — connection has no organizationId",
   581	        );
   582	        return;
   583	      }
   584	
   585	      // Stash the ROUTING row before posting (same durable-before-card policy
   586	      // as questions). A click must route with the conversation the card was
   587	      // posted for — rebuilding routing from the click event's thread forks a
   588	      // Slack DM (the card posts channel-level, so the click's thread id keys
   589	      // to the card's own ts) and loses history/teamId. The buttons therefore
   590	      // carry only `suggestion:<id>:<i>`; the prompt text and routing live in
   591	      // this row, which also keeps Telegram's 64-byte callback_data budget.
   592	      // Read-not-claim on click: chips stay multi-clickable by design. A row
   593	      // that is never tapped is swept with the shared 24h TTL.
   594	      await storePendingSuggestion(
   595	        event.id,
   596	        organizationId,
   597	        connectionId,
   598	        event.userId,
   599	        { suggestion: event },
   600	      );
   601	
   602	      const buttons = event.prompts.map((prompt, i) =>
   603	        Button({
   604	          id: `suggestion:${event.id}:${i}`,
   605	          label: prompt.title,
   606	        })
   607	      );
   608	      const card = Card({ children: [Actions(buttons)] });
   609	      // Platforms without card support get a numbered list. Each line shows the
   610	      // title only — the message can be a full sentence and would bury the list.
   611	      const fallbackText = event.prompts
   612	        .map((prompt, i) => `${i + 1}. ${prompt.title}`)
   613	        .join("\n");
   614	      await postWithFallback(
   615	        thread,
   616	        { card, fallbackText },
   617	        connectionId,
   618	        "suggestion interaction"
   619	      );
   620	    }

