 870	 * away. Absent in tests.
 871	 *
 872	 * `onQuestionClick` (optional) handles the `question:*` click path. Absent
 873	 * in tests that only exercise tool-approval flows.
 874	 *
 875	 * `onSuggestionClick` (optional) handles the `suggestion:*` click path. Absent
 876	 * in tests that only exercise tool-approval flows.
 877	 */
 878	export function registerActionHandlers(
 879	  chat: any,
 880	  connection: PlatformConnection,
 881	  grantStore: GrantStore | undefined,
 882	  executeToolDirect?: ExecuteToolDirectFn,
 883	  claimApprovalCard?: (requestId: string) => SentMessage | undefined,
 884	  onQuestionClick?: OnQuestionClickFn,
 885	  resolveApprovalTarget?: (
 886	    channelId: string,
 887			conversationId: string,
 888		) => Promise<any | null>,
 889	  onSuggestionClick?: OnSuggestionClickFn,
 890	): void {
 891		chat.onAction(async (event: any) => {
 892			const actionId: string = event.actionId ?? "";
 893			const value: string = event.value ?? "";
 894			const thread = event.thread;
 895	
 896			if (!thread || !actionId) return;
 897	
 898			// Handle durable run approvals from notification cards. This path is
 899			// intentionally scoped to entity_field_change: approving connector actions
 900			// from chat needs a separate env-safe execution path.
 901			if (actionId.startsWith("run-approval:")) {
 902				const [, runIdPart, decisionPart] = actionId.split(":");
