   104	 * installs need the worker PAT from /api/local-init for that surface, while
   105	 * admin REST + MCP need the Better Auth session token returned by getToken().
   106	 */
   107	export async function getAgentApiToken(
   108	  contextName?: string
   109	): Promise<string | null> {
   110	  const envToken = process.env.LOBU_API_TOKEN;
   111	  if (envToken) return envToken;
   112	
   113	  const token = await getCredentialsToken(contextName);
   114	  if (!token) return null;
   115	
   116	  let creds = await loadCredentials(contextName);
   117	  if (!creds?.localWorkerToken && (await isLoopbackContext(contextName))) {
   118	    creds = await tryLocalInit(contextName);
   119	  }
