     2		createLogger,
     3		getErrorMessage,
     4		verifyWorkerToken,
     5	} from "@lobu/core";
     6	import type { Context } from "hono";
     7	import type { McpProxy } from "./proxy.js";
     8	import {
     9		buildSessionKey,
    10		buildUpstreamHeaders,
    11		computeScopeKey,
    12		extractSessionToken,
    13		getRequestBodyAsText,
    14		type HttpMcpServerConfig,
    15		MAX_BODY_SIZE,
    16		runWithWorkerOrgContext,
    17		sendJsonRpcError,
    18		UPSTREAM_FETCH_TIMEOUT_MS,
    19		upstreamTimeoutSignal,
    20	} from "./proxy-shared.js";
    21	import { ssrfBlockResponse } from "./proxy-upstream.js";
    22	
    23	const logger = createLogger("mcp-proxy");
    24	
    25	export async function handleProxyRequest(
    26		proxy: McpProxy,
    27		c: Context,
    28	): Promise<Response> {
    29		const mcpId = c.req.param("mcpId") || c.req.header("x-mcp-id");
    30		const sessionToken = extractSessionToken(c);
    31	
    32		logger.info("Handling MCP proxy request", {
    33			method: c.req.method,
    34			path: c.req.path,
    35			mcpId,
    36			hasSessionToken: !!sessionToken,
    37		});
    38	
    39		if (!mcpId) {
    40			return sendJsonRpcError(c, -32600, "Missing MCP ID");
    41		}
    42	
    43		if (!sessionToken) {
    44			return sendJsonRpcError(c, -32600, "Missing authentication token");
    45		}
    46	
    47		const tokenData = verifyWorkerToken(sessionToken);
    48		if (!tokenData) {
    49			return sendJsonRpcError(c, -32600, "Invalid authentication token");
    50		}
    51		if (!tokenData.organizationId) {
    52			return sendJsonRpcError(c, -32600, "Worker token missing organizationId");
    53		}
    54	
    55		return runWithWorkerOrgContext(tokenData, () =>
    56			handleProxyRequestAuthenticated(proxy, c, mcpId, sessionToken, tokenData),
    57		);
    58	}
    59	
    60	async function handleProxyRequestAuthenticated(
    61		proxy: McpProxy,
    62		c: Context,
    63		mcpId: string,
    64		sessionToken: string,
    65		tokenData: NonNullable<ReturnType<typeof verifyWorkerToken>>,
    66	): Promise<Response> {
    67		const agentId = tokenData.agentId || tokenData.userId;
    68		const httpServer = await proxy.configService.getHttpServer(mcpId, agentId, tokenData.organizationId);
    69	
    70		if (!httpServer) {
    71			return sendJsonRpcError(c, -32601, `MCP server '${mcpId}' not found`);
    72		}
    73	
    74		// Pre-tool guardrails + tool approval for tools/call JSON-RPC requests.
    75		// Clone the request so the body can be read twice (once here, once in
    76		// forwardRequest). NOTE: this runs on any POST, NOT gated on grantStore —
    77		// guardrail enforcement must not depend on the approval subsystem being
    78		// configured (the approval check below is what's gated on grantStore).
    79		if (c.req.method === "POST") {
    80			try {
    81				const clonedReq = c.req.raw.clone();
    82				const bodyText = await clonedReq.text();
    83				if (bodyText) {
    84					const jsonRpc = JSON.parse(bodyText);
    85	
    86					// JSON-RPC 2.0 / the MCP streamable-HTTP transport permit BATCH
    87					// requests: a top-level ARRAY of request objects. The single-request
    88					// gate below keys on `jsonRpc.method`, which is `undefined` for an
    89					// array — so a batched `tools/call` would skip BOTH the pre-tool
    90					// guardrails and the approval gate and be forwarded verbatim, and a
    91					// spec-compliant upstream executes the whole batch. The worker's MCP
    92					// client never legitimately batches tool calls, so reject any batch
    93					// containing one rather than forward it unguarded. Batches with no
    94					// tools/call (e.g. notification batches) still pass through.
    95					if (Array.isArray(jsonRpc)) {
    96						if (jsonRpc.some((m) => m?.method === "tools/call")) {
    97							logger.warn(
    98								"Rejecting batched tools/call — guardrails and approval cannot be enforced on a JSON-RPC batch",
    99								{ mcpId, agentId },
   100							);
   101							return sendJsonRpcError(
   102								c,
   103								-32600,
   104								"Batched tools/call is not permitted; send each tool call as a single JSON-RPC request.",
   105							);
   106						}
   107					} else if (jsonRpc.method === "tools/call" && jsonRpc.params?.name) {
   108						const toolName = jsonRpc.params.name;
   109						const toolArgs = jsonRpc.params.arguments || {};
