   111						// Pre-tool guardrails run before approval so a blocked tool never
   112						// enters the approval funnel, and independently of grantStore.
   113						if (
   114							await proxy.runPreToolGuardrails(
   115								agentId,
   116								tokenData,
   117								toolName,
   118								toolArgs,
   119							)
   120						) {
   121							return c.json({
   122								jsonrpc: "2.0",
   123								id: jsonRpc.id,
   124								result: {
   125									content: [
   126										{ type: "text", text: "Tool call blocked by policy." },
   127									],
   128									isError: true,
   129								},
   130							});
   131						}
   132	
   133						// Tool approval is gated on the approval subsystem (grantStore).
   134						if (proxy.grantStore) {
   135							const approval = await proxy.evaluateToolApproval(
   136								mcpId,
   137								toolName,
   138								toolArgs,
   139								agentId,
   140								tokenData,
   141								sessionToken,
   142							);
   143							if (approval !== "allow") {
   144								return c.json({
   145									jsonrpc: "2.0",
   146									id: jsonRpc.id,
   147									result: {
   148										content: [
   149											{
   150												type: "text",
   151												text: "Tool call requires approval. The user has been asked to approve. Your session will end. The result will arrive as your next message.",
   152											},
   153										],
   154										isError: true,
   155									},
   156								});
   157							}
   158						}
   159					}
   160				}
   161			} catch {
   162				// If body parsing fails, just forward the request as-is
   163			}
   164		}
