   166		const scopeKey = computeScopeKey(tokenData.userId);
   167	
   168		try {
   169			return await forwardRequest(proxy, c, httpServer, agentId, mcpId, scopeKey, {
   170				workerToken: sessionToken,
   171			});
   172		} catch (error) {
   173			logger.error("Failed to proxy MCP request", { error, mcpId });
   174			return sendJsonRpcError(
   175				c,
   176				-32603,
   177				`Failed to connect to MCP '${mcpId}': ${error instanceof Error ? error.message : "Unknown error"}`,
   178			);
   179		}
   180	}
   181	
   182	async function forwardRequest(
   183		proxy: McpProxy,
   184		c: Context,
   185		httpServer: HttpMcpServerConfig,
   186		agentId: string,
   187		mcpId: string,
   188		scopeKey?: string,
   189		authContext?: {
   190			workerToken?: string;
   191		},
   192	): Promise<Response> {
   193		const ssrfBlock = await ssrfBlockResponse(httpServer, mcpId, agentId);
   194		if (ssrfBlock) {
   195			return sendJsonRpcError(
   196				c,
   197				-32600,
   198				"Upstream URL resolves to a blocked internal network",
   199			);
   200		}
   201	
   202		const sessionKey = buildSessionKey(agentId, mcpId, scopeKey);
   203		let sessionId = proxy.upstream.getSession(sessionKey);
   204	
   205		const bodyText = await getRequestBodyAsText(c);
   206	
   207		// Body size validation
   208		if (bodyText.length > MAX_BODY_SIZE) {
   209			logger.warn("Request body too large", {
   210				mcpId,
   211				agentId,
   212				size: bodyText.length,
   213			});
   214			return new Response("Request body too large", { status: 413 });
   215		}
   216	
   217		// Internal MCPs (lobu-memory) accept the worker JWT directly.
   218		const credentialToken = httpServer.internal
   219			? authContext?.workerToken
   220			: undefined;
   221	
   222		// If no active session exists, re-initialize before forwarding
   223		if (!sessionId && c.req.method === "POST") {
   224			try {
   225				await proxy.upstream.reinitializeSession(
   226					httpServer,
   227					agentId,
   228					mcpId,
   229					scopeKey,
   230					credentialToken,
   231				);
   232				sessionId = proxy.upstream.getSession(sessionKey);
   233			} catch (error) {
   234				logger.warn("Pre-emptive MCP re-initialization failed", {
   235					mcpId,
   236					error: getErrorMessage(error),
   237				});
   238			}
   239		}
   240	
   241		logger.info("Proxying MCP request", {
   242			mcpId,
   243			agentId,
   244			method: c.req.method,
   245			hasSession: !!sessionId,
   246			bodyLength: bodyText.length,
   247		});
   248	
   249		const headers = buildUpstreamHeaders(
   250			sessionId,
   251			credentialToken,
   252			httpServer.internal === true,
   253			proxy.upstream.getProtocolVersion(sessionKey),
   254		);
   255	
   256		let response = await fetch(httpServer.upstreamUrl, {
   257			method: c.req.method,
   258			headers,
   259			body: bodyText || undefined,
   260			signal: upstreamTimeoutSignal(c.req.method),
   261		});
   262	
   263		// Stale-session recovery: if upstream returns 404 we sent a session id
   264		// it no longer recognizes (e.g. server restart). Drop the cached id,
   265		// re-init, and retry once with the same payload. Only meaningful for
   266		// POST — GET/DELETE on an unknown session should surface the 404 as-is.
   267		if (
   268			response.status === 404 &&
   269			sessionId &&
   270			c.req.method === "POST" &&
   271			bodyText
   272		) {
   273			logger.info(
   274				"Upstream 404 on cached session id — re-initializing and retrying",
   275				{ mcpId, agentId },
   276			);
   277			try {
   278				await proxy.upstream.reinitializeSession(
   279					httpServer,
   280					agentId,
   281					mcpId,
   282					scopeKey,
   283					credentialToken,
   284				);
   285				sessionId = proxy.upstream.getSession(sessionKey);
   286				const retryHeaders = buildUpstreamHeaders(
   287					sessionId,
   288					credentialToken,
   289					httpServer.internal === true,
   290					proxy.upstream.getProtocolVersion(sessionKey),
   291				);
   292				response = await fetch(httpServer.upstreamUrl, {
   293					method: c.req.method,
   294					headers: retryHeaders,
   295					body: bodyText,
   296					// Retry path is POST-only (guarded above) — always bounded.
   297					signal: AbortSignal.timeout(UPSTREAM_FETCH_TIMEOUT_MS),
   298				});
   299			} catch (error) {
   300				logger.warn("Stale-session recovery failed on forward", {
   301					mcpId,
   302					error: getErrorMessage(error),
   303				});
   304			}
   305		}
   306	
   307		const newSessionId = response.headers.get("Mcp-Session-Id");
   308		if (newSessionId) {
   309			proxy.upstream.setSession(sessionKey, newSessionId);
   310			logger.debug("Stored MCP session ID", {
   311				mcpId,
   312				agentId,
   313				sessionId: newSessionId,
   314			});
   315		}
   316	
   317		const responseHeaders = new Headers();
   318		const contentType = response.headers.get("content-type");
   319		if (contentType) {
   320			responseHeaders.set("Content-Type", contentType);
   321		}
   322		if (newSessionId) {
   323			responseHeaders.set("Mcp-Session-Id", newSessionId);
   324		}
   325	
   326		return new Response(response.body, {
   327			status: response.status,
   328			headers: responseHeaders,
   329		});
   330	}

