503	 * Result: single object with `action` as a string enum (description
504	 * generated from the variants — see `buildActionEnumDescription`), all
505	 * other properties merged (first occurrence wins; only `action` is
506	 * required on the wire, per-action required fields surface in prose).
507	 */
508	function flattenUnionSchema(schema: any): any {
509	  const variants: any[] = schema.anyOf || schema.oneOf;
510	  const actionValues: string[] = [];
