515	  for (const variant of variants) {
516	    if (variant.type !== 'object' || !variant.properties) continue;
517	    const actionProp = variant.properties.action;
518	    const actionName = actionProp?.const;
519	    if (typeof actionName !== 'string') continue;
520	    actionValues.push(actionName);
521	    if (typeof actionProp?.description === 'string') {
522	      actionDescriptions.set(actionName, actionProp.description);
523	    }
524	    // Variant's `required` array carries non-Optional prop names — the
525	    // basis for the per-action "Required: ..." line in the enum description.
526	    const requiredFields = (variant.required ?? []).filter((k: string) => k !== 'action');
527	    if (requiredFields.length > 0) {
528	      actionRequired.set(actionName, requiredFields);
529	    }
530	    for (const [key, prop] of Object.entries<any>(variant.properties)) {
