180		sdkNamespace?: string,
181	) {
182		const manage = <T>(payload: object): Promise<T> =>
183			handler(payload as never, env, ctx) as Promise<T>;
184	
185		const action = async <T>(
186			actionName: string,
187			input: object = {},
188			/**
189			 * Public SDK method name. Defaults to the CAMEL-CASE of the internal
190			 * action (`generate_embeddings` → `generateEmbeddings`), which is the
191			 * actual method on most namespaces — a bare snake_case default would
192			 * render a nonexistent path like `client.classifiers.generate_embeddings`.
193			 * Namespaces whose public name diverges from the action (e.g. feeds
194			 * `read_feed` → `get`) pass it explicitly.
195			 */
196			publicMethod: string = snakeToCamel(actionName),
197		): Promise<T> => {
198			// Spread caller input FIRST, then force `action` so a caller-supplied
199			// `action` key (e.g. from a read-only query_sdk script) can never override
200			// the discriminator and reach a write/delete handler.
201			const { action: _ignored, ...rest } = input as Record<string, unknown>;
202			// Rewrite accepted field aliases (sdk-aliases.ts) to their canonical
203			// names — the same registry search_sdk renders, so discovery == runtime.
204			const canonical = sdkNamespace
205				? applyFieldAliases(`${sdkNamespace}.${publicMethod}`, rest)
206				: rest;
207			let result: T;
208			try {
209				result = await manage<T>({ ...canonical, action: actionName });
210			} catch (err) {
211				throw rewriteInternalToolName(err, sdkNamespace, publicMethod);
212			}
213			const failure = failureMessage(actionName, result);
214			if (failure) {
215				throw new ClientSdkActionError(
216					actionName,
217					failure.message,
218					failure.result,
219				);
220			}
221			return result;
222		};
223	
224		return { manage, action };
