 134	
 135	export function createMutation<TParams, TResult = unknown>(config: {
 136	  tool: string;
 137	  body: (params: TParams) => Record<string, unknown>;
 138	  invalidateKeys: string[];
 139	  transform?: (data: any) => TResult;
 140	  checkError?: boolean; // default true -- throw if result.error exists
 141	  // Static text, or a function of the mutation result for outcome-dependent
 142	  // toasts (return null to suppress -- e.g. a create that queued an approval
 143	  // instead of creating).
 144	  successMessage?: string | ((result: TResult) => string | null);
 145	  // Fallback toast text when a thrown error has no message. Defaults to the
 146	  // generic 'Something went wrong'.
 147	  errorMessage?: string;
 148	  // Also invalidate on ERROR, not just success. Set for actions whose failure
 149	  // usually means the UI is stale (e.g. approving a run another tab/replica
 150	  // already resolved — "Run not found or not pending"): refetching then removes
 151	  // the stale control that produced the error instead of leaving it clickable.
 152	  invalidateOnError?: boolean;
 153	}) {
 154	  return () => {
 155	    const queryClient = useQueryClient();
 156	    const invalidateAll = () => {
 157	      for (const key of config.invalidateKeys) {
 158	        queryClient.invalidateQueries({ queryKey: [key] });
 159	      }
 160	    };
 161	    return useMutation({
 162	      mutationFn: async (params: TParams) => {
 163	        const result = await apiCall<any>(config.tool, config.body(params));
 164	        if (config.checkError !== false && result.error) {
 165	          throw new Error(result.error);
 166	        }
 167	        return config.transform ? config.transform(result) : (result as TResult);
 168	      },
 169	      onSuccess: (result: TResult) => {
 170	        invalidateAll();
 171	        const message =
 172	          typeof config.successMessage === 'function'
 173	            ? config.successMessage(result)
 174	            : config.successMessage;
 175	        if (message) {
 176	          toast.success(message);
 177	        }
 178	      },
 179	      onError: (error: Error) => {
 180	        if (config.invalidateOnError) invalidateAll();
 181	        toast.error(error.message || config.errorMessage || 'Something went wrong');
 182	      },
 183	    });
 184	  };
 185	}
