 330	export async function apiCall<T>(
 331	  endpoint: string,
 332	  body: Record<string, unknown>,
 333	  orgContext?: string | ApiOrgContext,
 334	  options?: { timeoutMs?: number }
 335	): Promise<T> {
 336	  const scope = resolveApiScope(orgContext);
 337	  const response = await fetchWithTimeout(`${API_URL}/api/${scope.slug}/${endpoint}`, {
 338	    method: 'POST',
 339	    headers: {
 340	      'Content-Type': 'application/json',
 341	    },
 342	    credentials: 'include',
 343	    body: JSON.stringify(body),
 344	    timeoutMs: options?.timeoutMs,
 345	  });
 346	
 347	  if (!response.ok) {
 348	    throw await apiErrorFor(response);
 349	  }
 350	
 351	  return response.json();
