  1	/**
  2	 * Session resolution that does not depend on cookie order.
  3	 *
  4	 * One auth cookie name can exist at two scopes at once — host-only and
  5	 * `Domain=`-scoped — and the browser sends both in one header. Position then
  6	 * decides who authenticates, and position is not ours to choose: RFC 6265 §5.4
  7	 * sends the oldest first, better-call's `parseCookies` keeps the first
  8	 * occurrence (`if (!cookies.has(key))`), and `getSignedCookie` reads that one
  9	 * and stops. An older stale twin therefore outranks every later sign-in, which
 10	 * can never win because it is always the newer cookie. Prod, 2026-08-06:
 11	 * `dead; good` → null, `good; dead` → the session.
 12	 */
 13	
 14	import { sessionCookieName } from './session-cookie-scope';
 15	
 16	/** Both spellings coexist: a jar can outlive an http→https switch. */
 17	const SESSION_COOKIE_NAMES = [sessionCookieName(false), sessionCookieName(true)];
 18	
 19	/**
 20	 * `Cookie` is attacker-controlled and each probe is a session lookup, so an
 21	 * unbounded loop amplifies one request into ~100. Real jars hold two or three.
 22	 */
 23	const MAX_CANDIDATES = 8;
 24	
 25	type SessionCookieCandidate = { name: string; value: string };
 26	
 27	/** Generic, so wrapping `getSession` never widens what a call site sees. */
 28	type SessionReader = {
 29	  api: { getSession: (opts: { headers: Headers }) => Promise<any> };
 30	};
 31	type SessionOf<A extends SessionReader> = Awaited<ReturnType<A['api']['getSession']>>;
 32	
 33	/**
 34	 * Every session cookie in a `Cookie` header, in the order sent.
 35	 *
 36	 * Each keeps the name it arrived under: `getSession` reads exactly one name and
 37	 * is blind to the other spelling, so renaming a candidate hides it entirely.
 38	 */
 39	export function sessionCookieCandidates(
 40	  cookieHeader: string | null | undefined
 41	): SessionCookieCandidate[] {
 42	  if (!cookieHeader) return [];
 43	  const candidates: SessionCookieCandidate[] = [];
 44	  for (const part of cookieHeader.split(';')) {
 45	    const eq = part.indexOf('=');
 46	    if (eq === -1) continue;
 47	    // Exact name, so `<name>_other` is never mistaken for `<name>`.
 48	    const name = part.slice(0, eq).trim();
 49	    if (!SESSION_COOKIE_NAMES.includes(name)) continue;
 50	    const value = part.slice(eq + 1).trim();
 51	    if (value) candidates.push({ name, value });
 52	  }
 53	  return candidates;
 54	}
 55	
 56	/**
 57	 * `user`, not `user && session`: four call sites (auth/middleware.ts,
 58	 * auth/oauth/routes.ts, connect/routes.ts, worker-api/auth-runs.ts) check
 59	 * `user` alone, so a stricter test would reject on a duplicated jar what they
 60	 * accept on a clean one.
 61	 */
 62	function isLive(session: any): boolean {
 63	  return Boolean(session?.user);
 64	}
 65	
 66	/**
 67	 * The jar minus its session cookies. Companions must survive a probe:
 68	 * `better-auth.dont_remember` gates session-expiry refresh, so dropping it
 69	 * would give a duplicated jar different refresh terms than a clean one.
 70	 */
 71	function nonSessionCookies(cookieHeader: string | null): string[] {
 72	  if (!cookieHeader) return [];
 73	  const kept: string[] = [];
 74	  for (const part of cookieHeader.split(';')) {
 75	    const pair = part.trim();
 76	    const eq = pair.indexOf('=');
 77	    if (eq === -1) continue;
 78	    if (SESSION_COOKIE_NAMES.includes(pair.slice(0, eq).trim())) continue;
 79	    kept.push(pair);
 80	  }
 81	  return kept;
 82	}
 83	
 84	/**
 85	 * Drop-in for `auth.api.getSession({ headers })` that resolves on merit.
 86	 *
 87	 * A one-cookie jar takes the original call unchanged; the extra lookups happen
 88	 * only for a jar that is already broken.
 89	 */
 90	export async function resolveSession<A extends SessionReader>(
 91	  auth: A,
 92	  headers: Headers
 93	): Promise<SessionOf<A>> {
 94	  const live = await findLiveProbe(auth, headers);
 95	  if (!live) return await auth.api.getSession({ headers });
 96	  // Resolving on merit must not become "authenticate on anything".
 97	  return (live.session ?? null) as SessionOf<A>;
 98	}
 99	
100	/**
101	 * Probe an ambiguous jar one candidate at a time.
102	 *
103	 * `null` when the jar is not ambiguous. Otherwise the winning headers and the
104	 * session they produced — returning both keeps the lookup from being repeated —
105	 * with `session: null` when nothing verified.
106	 *
107	 * A probe changes exactly one thing: which session cookie is present. Other
108	 * headers and other cookies ride along, so `Authorization: Bearer` and origin
109	 * checks behave as before.
110	 */
111	async function findLiveProbe<A extends SessionReader>(
112	  auth: A,
113	  headers: Headers
114	): Promise<{ headers: Headers; session: SessionOf<A> | null } | null> {
115	  const cookieHeader = headers.get('cookie');
116	  const candidates = sessionCookieCandidates(cookieHeader);
117	  if (candidates.length <= 1) return null;
118	
119	  const companions = nonSessionCookies(cookieHeader);
120	  for (const candidate of candidates.slice(0, MAX_CANDIDATES)) {
121	    const probe = new Headers(headers);
122	    probe.set(
123	      'cookie',
124	      [...companions, `${candidate.name}=${candidate.value}`].join('; ')
125	    );
126	    const session = await auth.api.getSession({ headers: probe });
127	    if (isLive(session)) return { headers: probe, session };
128	  }
129	  // Placeholder headers: every caller branches on `session` before reading them.
130	  return { headers, session: null };
131	}
132	
133	/**
134	 * The jar with its ambiguity already removed, for code that must hand the
135	 * request to a reader that resolves it itself — Better Auth's `/api/auth/*`
136	 * handler. That is where `get-session` lives, the call the web app uses to ask
137	 * whether it is signed in, so leaving it order-dependent would keep the brick
138	 * visible in the UI with every internal call site fixed.
139	 *
140	 * Ordinary jars come back by identity, so the common path does not even copy.
141	 */
142	export async function collapseSessionCookies<A extends SessionReader>(
143	  auth: A,
144	  headers: Headers
145	): Promise<Headers> {
146	  const live = await findLiveProbe(auth, headers);
147	  if (!live) return headers;
148	  if (live.session) return live.headers;
149	
150	  // Nothing verified. Strip the session cookie rather than pass an arbitrary
151	  // dead twin, so sign-in and sign-out on this request cannot act on one.
152	  const companions = nonSessionCookies(headers.get('cookie'));
153	  const stripped = new Headers(headers);
154	  if (companions.length > 0) stripped.set('cookie', companions.join('; '));
155	  else stripped.delete('cookie');
156	  return stripped;
157	}
 88	
 89	**Integration suite prerequisites.** Node 22 is the repo default (`.node-version`); Lobu accepts Node 22–24 and 26+, while Node 25 boots without the SDK sandbox. Global setup uses `DATABASE_URL` if set, otherwise spawns an ephemeral embedded Postgres + pgvector.
 90	
 91	**Vitest 3.2.6 `list --shard=N/M` prints every file, even though `run --shard=N/M` partitions correctly.** Do not use `vitest list` to prove shard coverage. Run each shard with the JSON reporter and compare `testResults`: the three-way CI split owns 126 of 378 files per shard, with no overlap at execution time.
 92	
 93	**The test env speaks plain HTTP, so it validates the WRONG auth-cookie name.** Better Auth derives the session cookie name from `useSecureCookies`: tests get `better-auth.session_token`, prod gets `__Secure-better-auth.session_token`, and `getSession` reads exactly one of them and is blind to the other. Any code that *constructs* or *matches* that name can therefore pass a full red→green integration test and still fail in prod — #2578 nearly shipped a probe that rewrote every candidate to the bare basename, which would have locked out every duplicated jar in production (caught by `make review-fix`, not by the suite). Use `sessionCookieName(isHttps)` from `packages/server/src/auth/session-cookie-scope.ts`, never a literal, and cover **both** spellings explicitly. A unit test with a faked `getSession` is the stronger test here; the full-stack one inherits the harness's http-ness.
 94	
 95	**A cookie can be rejected two different ways, and the cheap fake only exercises one.** `better-call`'s `getSignedCookie` rejects a bad HMAC *before the database is consulted* (`context.mjs`: it also bails early on any signature that is not 44 base64 chars ending in `=`); a real stale twin is correctly signed and dies on the session lookup instead. A hand-written garbage token only ever tests the first path. To test the second, mint a real session and delete its `session` row.
 96	
 97	**`make dev` is not the test harness.** It migrates its owned local per-branch database and boots the app, but that does not exercise the branches a relevant unit or integration suite covers.
 98	
 99	**A scratch server that is "healthy" before the fresh initdb and migration logs appear is probably an orphan.** A cold embedded boot runs `initdb` as a subprocess, so a genuinely fresh server logs it; instant health means you reached a server that was already running. Confirm with the data dir rather than the clock — `<dir>/.lobu/pgdata/PG_VERSION` should exist and be newly created. Kill orphans by port, not name — `pkill -f "lobu run --port"` never matches, because the real cmdline is `node .../server.bundle.mjs`. Confirm what you are about to kill first (`lsof -iTCP:<port> -sTCP:LISTEN`, check it is the expected `server.bundle.mjs`), then `lsof -tiTCP:<port> -sTCP:LISTEN | xargs kill`. Reserve `-9` for a process that ignores the polite signal.
100

