162	const ORG_AGNOSTIC_TOOLS = new Set(['list_organizations']);
163	
164	export function checkToolAccess(toolName: string, args: unknown, authCtx: AuthContext): void {
165	  if (ORG_AGNOSTIC_TOOLS.has(toolName)) {
166	    if (!authCtx.isAuthenticated) {
167	      throw new Error('Authentication required.');
168	    }
169	    // list_organizations is read-tier; OAuth tokens without `mcp:read`
170	    // (e.g. profile-only) must not call it.
171	    if (!hasRequiredMcpScope('read', authCtx.scopes)) {
172	      throw new Error(
173	        'This MCP session does not include read access. Reconnect with read access to list organizations.'
174	      );
175	    }
176	    return;
177	  }
178	
179	  if (!authCtx.organizationId) {
180	    throw new Error('Organization context required. Authenticate with OAuth or API key.');
181	  }
182	
183	  const tool = getTool(toolName);
184	  // Genuinely unregistered → typed error so the REST proxy can fire a Sentry
185	  // alert (registry/frontend drift).
186	  if (!tool) {
187	    throw new ToolNotRegisteredError(toolName);
188	  }
189	
190	  const isReadOnly = isAuthorizationReadOnly(tool);
191	  const { memberRole: role } = authCtx;
192	  const requiredAccess = getRequiredAccessLevel(toolName, args, isReadOnly);
193	
194	  // Admin-tools run: the per-turn allowlist is a LIMIT on which
195	  // tools may exercise ADMIN-tier actions. Read/write-tier actions follow the
196	  // uniform role × scope model like every other caller.
197	  const adminAllowlist = authCtx.adminTools;
198	  if (
199	    requiredAccess === 'admin' &&
200	    adminAllowlist &&
201	    adminAllowlist.length > 0 &&
202	    !adminAllowlist.includes(toolName)
203	  ) {
204	    throw new Error(
205	      `This agent run may not perform admin actions with ${toolName}. Allowed admin tools: ${adminAllowlist.join(', ')}.`
206	    );
207	  }
208	
209	  if (!role && !isPublicReadable(toolName, args)) {
