  44	export async function routeAction<TResult>(
  45	  toolName: string,
  46	  action: string,
  47	  ctx: ToolContext,
  48	  handlers: Record<string, () => Promise<TResult>>
  49	): Promise<TResult> {
  50	  const handler = handlers[action];
  51	  if (!handler) {
  52	    // Unknown action is a caller/input fault (a 4xx), not an operational error.
  53	    throw new ToolUserError(`Unknown action: ${action}`, 400);
  54	  }
  55	
  56	  enforceActionAccess(toolName, action, ctx);
  57	
  58	  try {
  59	    return await handler();
  60	  } catch (error) {
  61	    // ToolUserError is an expected client fault (bad input, not-found,
  62	    // permission denied, conflict) that the REST/MCP layer turns into a 4xx for
  63	    // the caller — it is NOT an operational error. Logging it at `error` both
  64	    // spams the error log and (via the pino→Sentry bridge) created noisy alerts
  65	    // for routine 409/403 outcomes. Log at `warn` so it stays diagnosable
  66	    // without paging; genuine handler faults still log at `error`.
  67	    logger[errorLogLevel(error)](
  68	      {
  69	        error,
  70	        error_message: getErrorMessage(error),
  71	        error_stack: error instanceof Error ? error.stack : undefined,
  72	      },
  73	      `${toolName} error:`
  74	    );
  75	    throw error;
  76	  }
  77	}
