packages/server/src/tools/admin/action-tool.ts:79:export function defineActionTool<T extends AnyActions>(
     1	/**
     2	 * Generic factory for action-discriminated admin tools.
     3	 *
     4	 * The `manage_*` tools all share the same shape: an `action` discriminator,
     5	 * a per-action handler, and dispatch via `routeAction` (which enforces the
     6	 * per-action access policy). This module lets a tool declare itself as a map
     7	 * of `action -> { schema, handler }` instead of hand-rolling that plumbing.
     8	 *
     9	 * Two flavors, matching the two schema shapes that exist today:
    10	 *
    11	 * - `defineActionTool` — for tools whose input schema is a `Type.Union` of
    12	 *   per-action variants (one `Type.Object` with an `action` literal each).
    13	 *   The factory derives the union schema from the declared variants, so the
    14	 *   exposed JSON schema is identical to the previous hand-written
    15	 *   `Type.Union([...])` as long as variants are declared in the same order.
    16	 *   Args are coerced + validated against the matched variant before dispatch
    17	 *   (`withValidatedArgs`), so per-action required fields come from the schema.
    18	 *
    19	 * - `defineFlatActionTool` — for tools that intentionally expose a single
    20	 *   flat object schema with an `action` enum (kept flat for MCP clients and
    21	 *   because the registry's per-action public/access filtering only applies
    22	 *   to union variants — flattening a union here would change the exposed
    23	 *   schema). The flat schema stays declared in the tool file; the factory
    24	 *   only provides dispatch + required-field checks.
    25	 *
    26	 * Handler signature is `(args, ctx, env)` — `ctx` before `env` because most
    27	 * handlers need the context but not the environment, and trailing unused
    28	 * params can simply be omitted.
    29	 */
    30	
    31	import type { Static, TObject, TUnion } from '@sinclair/typebox';
    32	import { Type } from '@sinclair/typebox';
    33	import type { Env } from '../../index';
    34	import type { ToolContext } from '../registry';
    35	import { withValidatedArgs } from '../validate-args';
    36	import { requireField, routeAction } from './action-router';
    37	
    38	interface ActionDefinition<S extends TObject = TObject, R = unknown> {
    39	  /** TypeBox variant for this action (must carry the `action` literal). */
    40	  schema: S;
    41	  handler: (args: Static<S>, ctx: ToolContext, env: Env) => Promise<R>;
    42	}
    43	
    44	/** Pair an action's TypeBox variant with its typed handler. */
    45	export function action<S extends TObject, R>(
    46	  schema: S,
    47	  handler: (args: Static<S>, ctx: ToolContext, env: Env) => Promise<R>
    48	): ActionDefinition<S, R> {
    49	  return { schema, handler };
    50	}
    51	
    52	type AnyActions = Record<string, ActionDefinition<any, any>>;
    53	
    54	type ArgsOf<T extends AnyActions> = Static<T[keyof T]['schema']>;
    55	type ResultOf<T extends AnyActions> = Awaited<ReturnType<T[keyof T]['handler']>>;
    56	
    57	function runActions<T extends AnyActions>(
    58	  toolName: string,
    59	  actions: T,
    60	  args: ArgsOf<T>,
    61	  env: Env,
    62	  ctx: ToolContext
    63	): Promise<ResultOf<T>> {
    64	  const record = args as Record<string, unknown> & { action: string };
    65	  const handlers: Record<string, () => Promise<ResultOf<T>>> = {};
    66	  for (const [name, def] of Object.entries(actions)) {
    67	    handlers[name] = () => def.handler(args, ctx, env);
    68	  }
    69	  return routeAction<ResultOf<T>>(toolName, record.action, ctx, handlers);
    70	}
    71	
    72	/**
    73	 * Define a union-schema action tool. Returns the derived `Type.Union` input
    74	 * schema (variants in declaration order) and the `(args, env, ctx)` runner
    75	 * used as the registry handler. The runner coerces + validates args against
    76	 * the matched action variant before dispatch (lobu#1137), so per-action
    77	 * required fields are enforced by the schema, not `requires` lists.
    78	 */
    79	export function defineActionTool<T extends AnyActions>(
    80	  toolName: string,
    81	  actions: T
    82	): {
    83	  schema: TUnion<Array<T[keyof T]['schema']>>;
    84	  run: (args: ArgsOf<T>, env: Env, ctx: ToolContext) => Promise<ResultOf<T>>;
    85	} {
    86	  const schema = Type.Union(Object.values(actions).map((def) => def.schema)) as TUnion<
    87	    Array<T[keyof T]['schema']>
    88	  >;
    89	  return {
    90	    schema,
    91	    run: withValidatedArgs(toolName, schema, (args: ArgsOf<T>, env: Env, ctx: ToolContext) =>
    92	      runActions(toolName, actions, args, env, ctx)
    93	    ),
    94	  };
    95	}
    96	
    97	/**
    98	 * Define a flat-schema action tool: the tool keeps its hand-written flat
    99	 * object schema; the factory provides typed dispatch + required-field checks.
   100	 * Actions missing from the map fail with `Unknown action: ...` (routeAction).
   101	 */
   102	export function defineFlatActionTool<TArgs extends { action: string }, R>(
   103	  toolName: string,
   104	  actions: {
   105	    [A in TArgs['action']]?: {
   106	      requires?: string[];
   107	      handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R>;
   108	    };
   109	  }
   110	): (args: TArgs, env: Env, ctx: ToolContext) => Promise<R> {
   111	  return (args, env, ctx) => {
   112	    const record = args as Record<string, unknown> & { action: string };
   113	    const handlers: Record<string, () => Promise<R>> = {};
   114	    for (const [name, def] of Object.entries(actions) as Array<
   115	      [string, { requires?: string[]; handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R> }]
   116	    >) {
   117	      handlers[name] = () => {
   118	        for (const field of def.requires ?? []) {
   119	          requireField(record[field], field, name);
   120	        }
   121	        return def.handler(args, ctx, env);
   122	      };
   123	    }
   124	    return routeAction<R>(toolName, args.action, ctx, handlers);
   125	  };
   126	}
   127	
   128	/** Shorthand for a flat-tool action entry. */
   129	export function flatAction<TArgs extends { action: string }, R>(
   130	  handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R>,
   131	  options?: { requires?: string[] }
   132	): { requires?: string[]; handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R> } {
   133	  return { handler, requires: options?.requires };
   134	}

