 * Rejecting `ctx.clientId` alone is not enough: an in-process watcher/system
 * context runs with `userId=null` and NO client id, so it would slip past a
 * client-id-only guard AND past {@link isSystemContext}'s role bypass — letting
 * an automation approve a run it queued (sol review #3). We therefore require a
 * positive human identity: `userId` present, and no agent identity on the
 * context. Returns an error result (surfaced to the caller) or null when the
 * context is a genuine human. One gate, called by every approve/reject entry.
 */
function requireHumanApprovalContext(
	ctx: ToolContext,
	verb: "approve" | "reject",
): { error: string } | null {
	if (ctx.agentId || ctx.clientId) {
		return {
			error: `Operation ${verb === "approve" ? "approval" : "rejection"} requires a human web session. Agents cannot ${verb} operations.`,
		};
	}
	if (!ctx.userId) {
		return {
			error: `Operation ${verb === "approve" ? "approval" : "rejection"} requires a signed-in user. This request has no verified human identity.`,
		};
	}
	return null;
}

/**
 * The admin-or-run-owner gate shared by approve/reject, layered ON TOP of
 * {@link requireHumanApprovalContext} (which every caller runs first, so a
 * verified human identity is already guaranteed here). The tool-access tier
 * admits write-tier members so a recorded field owner can decide their own
 * run; everyone else non-admin gets the same admin-access denial the action
 * tier used to throw. No system-context bypass — a run decision is always human.
 */
async function requireApprovalAuthority(
	action: "approve" | "reject",
	runId: number,
	ctx: ToolContext,
): Promise<void> {
	if (isAdminOrOwnerRole(ctx.memberRole)) return;
	if (await isPendingEntityRunOwner(runId, ctx.organizationId, ctx.userId)) {
		return;
	}
	throw new Error(
		`This operation (${action}) requires admin or owner access. Ask an organization owner to grant elevated access.`,
	);
}
type ResolveLobuApprovalArgs = Static<typeof ResolveLobuApprovalSchema>;

const resolveLobuApprovalImpl = async (
  args: ResolveLobuApprovalArgs,
  env: Env,
  ctx: ToolContext
): Promise<LobuView> => {
  const capability = readApprovalCapability(ctx.mcpAppApprovalCapability);
  if (
    capability.runId !== args.run_id ||
    ctx.mcpAppsSupported !== true ||
    capability.organizationId !== ctx.organizationId ||
    capability.userId !== ctx.userId ||
    capability.clientId !== ctx.clientId ||
    capability.sessionId !== ctx.mcpSessionId ||
    capability.expiresAt <= Date.now()
  ) {
    throw new ToolUserError('The MCP App approval capability is stale or does not match.', 403);
  }

  const current = await findApprovalRow(args.run_id, env, ctx);
  if (current.interaction_status !== 'pending' || current.id !== capability.eventId) {
    throw new ToolUserError('This approval capability is stale; the run is no longer pending.', 409);
  }
  if (belongsToApprovalWindow(current)) {
    throw new ToolUserError('Batched proposals must be reviewed in Lobu.', 409);
  }

  // The encrypted capability proves a signed-in OAuth user deliberately used
  // this app surface. The canonical approval handler still performs its own
  // membership and run-owner/admin authority checks; clear only the non-human
  // transport identities after the capability has been fully revalidated.
  const humanContext: ToolContext = {
    ...ctx,
    agentId: null,
    clientId: null,
    mcpAppApprovalCapability: null,
  };
  const result = await manageOperations(
    args.decision === 'approve'
      ? { action: 'approve', run_id: args.run_id, ...(args.input ? { input: args.input } : {}) }
      : { action: 'reject', run_id: args.run_id, ...(args.reason ? { reason: args.reason } : {}) },
    env,
    humanContext
  );
  if ('error' in result && typeof result.error === 'string') {
    throw new ToolUserError(result.error, 409);
  }
  return buildApprovalView(args.run_id, env, ctx);
};

export const resolveLobuApproval = withValidatedArgs(
  'resolve_lobu_approval',
  ResolveLobuApprovalSchema,
  resolveLobuApprovalImpl
);
