/**
 * MCP Authentication Tests
 *
 * Tests for MCP endpoint authentication including:
 * - OAuth access tokens
 * - Personal Access Tokens (PATs)
 * - Unauthenticated discovery requests
 */

import { MCP_PROTOCOL_VERSION } from '@lobu/core';
import { beforeAll, describe, expect, it } from 'vitest';
import { clearInMemoryMcpSessionsForTests } from '../../../mcp-handler';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  addUserToOrganization,
  createExpiredAccessToken,
  createTestAccessToken,
  createTestAgent,
  createTestDeviceCode,
  createTestEntity,
  createTestOAuthClient,
  createTestOrganization,
  createTestPAT,
  createTestSession,
  createTestUser,
  seedSystemEntityTypes,
} from '../../setup/test-fixtures';
import { del, get, mcpListTools, mcpRequest, mcpToolsCall, post } from '../../setup/test-helpers';

describe('MCP Authentication', () => {
  let org: Awaited<ReturnType<typeof createTestOrganization>>;
  let publicOrg: Awaited<ReturnType<typeof createTestOrganization>>;
  let org2: Awaited<ReturnType<typeof createTestOrganization>>;
  let user: Awaited<ReturnType<typeof createTestUser>>;
  let client: Awaited<ReturnType<typeof createTestOAuthClient>>;
  let agent: Awaited<ReturnType<typeof createTestAgent>>;
  let publicEntity: Awaited<ReturnType<typeof createTestEntity>>;
  let sessionCookie: string;

  beforeAll(async () => {
    await cleanupTestDatabase();
    await seedSystemEntityTypes();
    org = await createTestOrganization({ name: 'Test Org' });
    publicOrg = await createTestOrganization({
      name: 'Public Org',
      visibility: 'public',
    });
    org2 = await createTestOrganization({ name: 'Second Org' });
    user = await createTestUser({});
    await addUserToOrganization(user.id, org.id);
    await addUserToOrganization(user.id, org2.id);
    client = await createTestOAuthClient();
    agent = await createTestAgent({
      organizationId: org.id,
      agentId: 'lobu-test-agent',
      ownerUserId: user.id,
    });
    publicEntity = await createTestEntity({
      name: 'Public Brand',
      organization_id: publicOrg.id,
      entity_type: 'brand',
    });
    const session = await createTestSession(user.id);
    sessionCookie = session.cookieHeader;
  });

  describe('Unauthenticated Requests', () => {
    it('rejects an MCP authorization request that omits its RFC 8707 resource', async () => {
      const query = new URLSearchParams({
        client_id: client.client_id,
        redirect_uri: client.redirect_uris.at(0) ?? '',
        response_type: 'code',
        scope: 'mcp:read',
        code_challenge: 'test-pkce-challenge',
        code_challenge_method: 'S256',
      });
      const response = await get(`/oauth/authorize?${query.toString()}`);

      expect(response.status).toBe(400);
      expect(await response.json()).toEqual({
        error: 'invalid_request',
        error_description: 'A valid same-origin MCP resource is required',
      });
    });

    it('challenges unauthenticated requests on the unscoped /mcp endpoint with 401 + WWW-Authenticate', async () => {
      const response = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: 1,
          method: 'tools/list',
          params: {},
        },
      });

      expect(response.status).toBe(401);
      expect(response.headers.get('WWW-Authenticate')).toBe(
        'Bearer resource_metadata="http://localhost/.well-known/oauth-protected-resource/mcp", scope="mcp:read mcp:write"'
      );
    });

    // SKIP: post-#438 the unscoped /mcp endpoint refuses ALL anonymous POSTs
    // (including initialize) with 401 + WWW-Authenticate. The original test
    // assumed an anonymous initialize would create a session that subsequent
    // GETs could probe; that path no longer exists. The first test in this
    // describe block ("challenges unauthenticated requests…") covers the
    // 401 challenge contract directly.
    it.skip('returns an OAuth challenge for anonymous root session stream requests', async () => {
      const initResponse = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: '__test_init__',
          method: 'initialize',
          params: {
            protocolVersion: '2025-03-26',
            capabilities: {},
            clientInfo: { name: 'lobu-test', version: '1.0' },
          },
        },
      });

      const sessionId = initResponse.headers.get('mcp-session-id');
      expect(sessionId).toBeTruthy();

      const response = await get('/mcp', {
        headers: {
          Accept: 'text/event-stream',
          'mcp-session-id': sessionId!,
        },
      });

      expect(response.status).toBe(401);
      expect(response.headers.get('WWW-Authenticate')).toContain(
        '/.well-known/oauth-protected-resource'
      );
    });

    // SKIP: post-#438 unscoped /mcp anonymous initialize returns 401 with no
    // session ID. This test's "anonymous-then-upgrade" flow is no longer
    // possible — the upgrade path is to start with an authenticated initialize.
    // The "challenges unauthenticated requests…" test above already verifies
    // the 401 contract.
    it.skip('upgrades an anonymous unscoped session when Bearer token is provided', async () => {
      const initResponse = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: '__test_init__',
          method: 'initialize',
          params: {
            protocolVersion: '2025-03-26',
            capabilities: {},
            clientInfo: { name: 'lobu-test', version: '1.0' },
          },
        },
      });

      const sessionId = initResponse.headers.get('mcp-session-id');
      expect(sessionId).toBeTruthy();

      // Anonymous tool call should be rejected
      const anonResponse = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: 1,
          method: 'tools/call',
          params: {
            name: 'search_memory',
            arguments: { query: 'upgrade-test-probe' },
          },
        },
        headers: { 'mcp-session-id': sessionId! },
      });
      expect(anonResponse.status).toBe(401);

      // Re-initialize with a new anonymous session (previous was cleared)
      const initResponse2 = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: '__test_init_2__',
          method: 'initialize',
          params: {
            protocolVersion: '2025-03-26',
            capabilities: {},
            clientInfo: { name: 'lobu-test', version: '1.0' },
          },
        },
      });
      const sessionId2 = initResponse2.headers.get('mcp-session-id');
      expect(sessionId2).toBeTruthy();

      // Now provide a Bearer token on the same session — should upgrade auth
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id);
      const authResponse = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: 2,
          method: 'tools/call',
          params: {
            name: 'search_memory',
            arguments: { query: 'upgrade-test-probe-after-auth' },
          },
        },
        headers: { 'mcp-session-id': sessionId2! },
        token,
      });
      expect(authResponse.status).toBe(200);
      const body = await authResponse.json();
      expect(body.error).toBeUndefined();
      expect(body.result).toBeDefined();
    });

    it('rejects anonymous public-readable tool calls for private workspaces', async () => {
      const response = await post(`/api/${org.slug}/resolve_path`, {
        body: {
          path: `/${org.slug}`,
          include_bootstrap: true,
        },
      });

      expect(response.status).toBe(401);

      const body = await response.json();
      expect(body.error).toBe('invalid_token');
    });

    it('should reject org-bound PAT on a different organization route', async () => {
      const org2 = await createTestOrganization({ name: 'PAT Other Org' });
      await addUserToOrganization(user.id, org2.id);
      const { token } = await createTestPAT(user.id, org.id);

      const response = await post(`/mcp/${org2.slug}`, {
        body: {
          jsonrpc: '2.0',
          id: 1,
          method: 'tools/list',
          params: {},
        },
        token,
      });

      expect(response.status).toBe(403);
      const body = await response.json();
      expect(body.error).toBe('forbidden');
      expect(body.error_description).toContain(
        'Token organization does not match URL organization'
      );
    });

    it('allows OAuth access token to cross-org when user has membership', async () => {
      // PATs are intentionally org-scoped (above), but OAuth tokens bind to
      // whichever org the user picked at consent time and the membership
      // check is the real authorization gate. Without this, `lobu login`
      // (which OAuths into one org) would lock the user out of every other
      // org they're admin in — including from minting a PAT for that org.
      //
      // We assert the auth gate passes (not 403 with the cross-org message),
      // not full MCP-handshake success — that needs initialize + notify and
      // is covered elsewhere.
      const org2 = await createTestOrganization({
        name: 'OAuth Cross-Org Target',
      });
      await addUserToOrganization(user.id, org2.id);
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id);

      const response = await post(`/mcp/${org2.slug}`, {
        body: {
          jsonrpc: '2.0',
          id: 1,
          method: 'tools/list',
          params: {},
        },
        token,
      });

      // Anything but the cross-org auth rejection is fine — 400 (missing
      // MCP session) is the expected next failure since the test skips
      // initialize, but 200 is also OK if the route gets that far.
      expect(response.status).not.toBe(403);
    });

    it('rejects OAuth cross-org call when user is not a member', async () => {
      const org2 = await createTestOrganization({ name: 'OAuth Stranger Org' });
      // Deliberately not adding user to org2.
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id);

      const response = await post(`/mcp/${org2.slug}`, {
        body: {
          jsonrpc: '2.0',
          id: 1,
          method: 'tools/list',
          params: {},
        },
        token,
      });

      expect(response.status).toBe(403);
      const body = await response.json();
      expect(body.error).toBe('forbidden');
      expect(body.error_description).toContain('not a member');
    });

    it('should reject PAT without owl_pat_ prefix', async () => {
      const response = await post('/mcp', {
        body: {
          jsonrpc: '2.0',
          id: 1,
          method: 'tools/list',
          params: {},
        },
        token: 'not_a_valid_pat_format',
      });

      expect(response.status).toBe(401);
    });
  });

  describe('Scoped /mcp/{slug} membership-role resolution', () => {
    // Regression: scoped sessions derived org from the URL slug and user from
    // the token but never looked up the caller's membership row, so `memberRole`
    // stayed null even for an owner — role-gated actions wrongly denied real
    // members. `connections.install_connector` is a genuinely admin-only action
    // (OWNER_ADMIN_ACTIONS); `catalog.list_installed` is READ-tier (a normal
    // token discovers connectors). Together they prove the role resolved AND
    // isn't over-granted.
    it('resolves an OWNER role on a scoped session (admin-only action allowed)', async () => {
      const roleOrg = await createTestOrganization({ name: 'Scoped Role Org' });
      const owner = await createTestUser({});
      await addUserToOrganization(owner.id, roleOrg.id, 'owner');
      const { token } = await createTestPAT(owner.id, roleOrg.id, {
        scope: 'mcp:read mcp:write mcp:admin',
      });

      // install_connector requires admin/owner. Pre-fix this threw
      // "requires ... admin access" on the scoped endpoint because memberRole
      // was null. run_sdk exposes write/admin methods (query_sdk does not), so
      // this genuinely reaches the admin gate. A bad connector_id still reaches
      // the handler (proving the access gate passed) and fails with a business
      // error, not an auth denial.
      const result = await mcpToolsCall(
        'run_sdk',
        {
          script:
            'export default async (_c, client) => { try { await client.connections.installConnector({ connector_id: "__nonexistent__" }); return { denied: false }; } catch (e) { return { denied: /admin/i.test(String(e && e.message)), msg: String(e && e.message) }; } }',
        },
        { token, orgSlug: roleOrg.slug }
      );
      // Owner is NOT denied by the admin gate (it may fail for a missing
      // connector, but never with an admin-access denial).
      expect(result.return_value?.denied).toBe(false);
    });

    it('lets a normal MEMBER discover connectors (list_installed is read-tier) but NOT do admin actions', async () => {
      const roleOrg = await createTestOrganization({
        name: 'Scoped Member Org',
      });
      const member = await createTestUser({});
      await addUserToOrganization(member.id, roleOrg.id, 'member');
      const { token } = await createTestPAT(member.id, roleOrg.id, {
        scope: 'mcp:read mcp:write',
      });

      // READ-tier discovery works for a plain member with a default-scoped token.
      const discover = await mcpToolsCall(
        'query_sdk',
        {
          script:
            'export default async (_c, client) => { await client.catalog.listInstalled({ kinds: ["connectors"] }); return { ok: true }; }',
        },
        { token, orgSlug: roleOrg.slug }
      );
      expect(discover.success).toBe(true);

      // But an admin-only action is still denied (no over-grant). run_sdk DOES
      // expose installConnector, so this reaches the admin gate — and a default
      // (mcp:read mcp:write) member token is denied there. This proves the
      // member's role resolved AND was not over-granted, the mirror of the
      // owner case above.
      const admin = await mcpToolsCall(
        'run_sdk',
        {
          script:
            'export default async (_c, client) => { await client.connections.installConnector({ connector_id: "__nonexistent__" }); return { ok: true }; }',
        },
        { token, orgSlug: roleOrg.slug }
      );
      expect(admin.success).toBe(false);
      expect(admin.error?.message).toMatch(
        /admin or owner access|admin access|not a function|not available/i
      );
    });
  });

  // The pre-#438 "JSON-RPC -32001 Organization context required" error path
  // no longer exists — anonymous calls now get HTTP 401 with WWW-Authenticate
  // before they ever reach the org-context guard. That contract is covered
  // by "challenges unauthenticated requests…" in the Unauthenticated block.
  describe('JSON-RPC Error Handling', () => {
    it('should handle malformed JSON-RPC requests', async () => {
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id);

      const response = await post('/mcp', {
        body: {
          // Missing jsonrpc version
          id: 1,
          method: 'tools/list',
        },
        token,
      });

      // Should either reject or handle gracefully
      expect(response.status).toBeLessThan(500);
      // Body should be valid JSON regardless of success/failure
      const body = await response.json();
      expect(body).toBeDefined();
    });
  });

  describe('tools/list Response', () => {
    it('should return list of available tools', async () => {
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id, {
        scope: 'mcp:read mcp:write mcp:admin',
      });

      const result = await mcpListTools({ token, orgSlug: org.slug });

      expect(result.tools).toBeInstanceOf(Array);

      // MCP tools/list is the agent surface only — admin flat tools dispatch
      // via REST and tools/call by name but are not advertised here.
      const toolNames = result.tools.map((t: any) => t.name);
      expect(toolNames.sort()).toEqual(
        [
          'query_sdk',
          'query_sql',
          'render_lobu_view',
          'run_sdk',
          'save_memory',
          'search_memory',
          'search_sdk',
        ].sort()
      );
      expect(toolNames).not.toContain('list_organizations');
      expect(toolNames).not.toContain('list_metrics');
      expect(toolNames).not.toContain('query_metric');
      expect(toolNames).not.toContain('metric_series');
      expect(toolNames).not.toContain('list_watchers');
      expect(toolNames).not.toContain('manage_entity');
      expect(toolNames).not.toContain('read_knowledge');
      expect(toolNames).not.toContain('execute');
      expect(toolNames).not.toContain('join_organization');
    });

    it('lists Behaviors through the consolidated internal admin tool', async () => {
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id);

      const result = await mcpToolsCall<{ behaviors?: unknown[] }>(
        'manage_behaviors',
        { action: 'list', status: 'active' },
        { token, orgSlug: org.slug }
      );
      expect(Array.isArray(result.behaviors)).toBe(true);
    });

    it('should include tool descriptions', async () => {
      const { token } = await createTestAccessToken(user.id, org.id, client.client_id);

      const result = await mcpListTools({ token });

      for (const tool of result.tools) {
        expect(tool.name).toBeDefined();
        expect(tool.description).toBeDefined();
/**
 * Composable test clients for the post-#348 MCP surface.
 *
 *   TestMcpClient  — full HTTP/JSON-RPC round-trip. Exercises auth, session
 *                    init, tool dispatch, and (for `runSdk`/`querySdk`) the
 *                    isolated-vm sandbox. Use it for tests that have to
 *                    verify MCP wire behavior (auth headers, JSON-RPC error
 *                    framing, sandbox timeouts). Surface mirrors the public
 *                    MCP tools: `searchSdk`, `searchMemory`, `saveMemory`,
 *                    `querySql`, `resolvePath`, `listOrganizations`, `runSdk`,
 *                    `querySdk`, plus a `raw()` escape hatch.
 *
 *   TestApiClient  — direct handler imports. Skips HTTP/sandbox; calls the
 *                    same namespace builders the sandbox exposes. Fast,
 *                    deterministic, and the right tool for CRUD permutations,
 *                    cross-org isolation, and error-path edges. Surface is
 *                    the typed SDK: `client.entities`, `client.behaviors`,
 *                    `client.classifiers`, etc. — `withAuth()` produces a new
 *                    client with overridden role/scopes for denial-path tests.
 *
 * The two surfaces are deliberately not interchangeable. `TestMcpClient.runSdk()`
 * is the wire-level analogue of `TestApiClient.entities.create(...)`; pick
 * the layer that matches what you're testing rather than swapping them.
 */

import type { Env } from '../../index';
import type { ToolContext, TokenType } from '../../tools/registry';
import {
  buildAuthProfilesNamespace,
  buildBehaviorsNamespace,
  buildClassifiersNamespace,
  buildConnectionsNamespace,
  buildEntitiesNamespace,
  buildEntitySchemaNamespace,
  buildFeedsNamespace,
  buildKnowledgeNamespace,
  buildOperationsNamespace,
  buildOrganizationsNamespace,
  buildViewTemplatesNamespace,
} from '../../sandbox/namespaces';
import { initWorkspaceProvider } from '../../workspace';
import {
  addUserToOrganization,
  createTestOrganization,
  createTestUser,
  type TestOrganization,
  type TestUser,
} from './test-fixtures';
import { mcpRequest, mcpToolsCall } from './test-helpers';

/**
 * Global init the namespace handlers depend on (URL building, slug lookup).
 * The HTTP test-helpers do this lazily via `ensureWorkspaceProvider`; the
 * direct-handler client has no request lifecycle, so we trigger the init
 * the first time TestApiClient is constructed and cache the promise.
 */
let workspaceReady: Promise<unknown> | null = null;
function ensureWorkspaceReady(): Promise<unknown> {
  if (!workspaceReady) {
    workspaceReady = initWorkspaceProvider();
  }
  return workspaceReady;
}

// ── shared types ─────────────────────────────────────────────────────────

export interface TestClientAuth {
  /** Required for any non-org-agnostic call. */
  organizationId: string;
  /** OAuth user; null for anonymous public reads. */
  userId: string | null;
  /** Member role in the org; null for non-members reading a public workspace. */
  memberRole: 'owner' | 'admin' | 'member' | null;
  /** OAuth scopes; defaults to full ['mcp:read', 'mcp:write', 'mcp:admin'] when
   * not supplied. Tests asserting scope-denial paths must override this. */
  scopes?: string[];
  /** Optional durable agent identity for the session. */
  agentId?: string;
  /** Token kind. Defaults to 'oauth' for authenticated users, 'anonymous'
   * otherwise. Some handlers (e.g. cross-org `client.org()`) gate on this. */
  tokenType?: TokenType;
  /** True when the MCP URL pinned an org slug (e.g. `/mcp/acme`). When the
   * direct-handler client is used, set this to mirror the wire intent. */
  scopedToOrg?: boolean;
}

const DEFAULT_TEST_ENV: Env = {
  ENVIRONMENT: 'test',
  DATABASE_URL: process.env.DATABASE_URL,
  JWT_SECRET: 'test-jwt-secret-for-testing-only',
  BETTER_AUTH_SECRET: 'test-auth-secret-for-testing-only',
  MAX_CONSECUTIVE_FAILURES: '3',
  RATE_LIMIT_ENABLED: 'false',
  EMBEDDINGS_SERVICE_URL: process.env.EMBEDDINGS_SERVICE_URL,
  EMBEDDINGS_SERVICE_TOKEN: process.env.EMBEDDINGS_SERVICE_TOKEN,
  EMBEDDINGS_TIMEOUT_MS: process.env.EMBEDDINGS_TIMEOUT_MS,
};

// ── HTTP layer (MCP JSON-RPC) ───────────────────────────────────────────

/**
 * Wire-level test client. Boots no HTTP server — calls go straight into the
 * Hono app via `app.fetch`. Use when the test has to verify behavior the
 * sandbox or auth layer adds on top of the raw handler.
 */
export class TestMcpClient {
  constructor(
    private readonly opts: {
      token: string;
      /** Pin the MCP session to `/mcp/{slug}`. Required for any tool other than
       * `list_organizations`; without it, the auth middleware never derives an
       * organizationId and every call fails with "Organization context required". */
      orgSlug?: string;
      env?: Partial<Env>;
      agentId?: string;
    }
  ) {}

  // ── direct MCP tools ─────────────────────────────────────────────────

  async listOrganizations(args: Record<string, unknown> = {}) {
    return mcpToolsCall('list_organizations', args, this.opts);
  }

  async resolvePath(path: string) {
    return mcpToolsCall('resolve_path', { path }, this.opts);
  }

  async searchSdk(args: { query: string; limit?: number }) {
    return mcpToolsCall('search_sdk', args, this.opts);
  }

  async searchMemory(args: Record<string, unknown>) {
    return mcpToolsCall('search_memory', args, this.opts);
  }

  async saveMemory(args: Record<string, unknown>) {
    return mcpToolsCall('save_memory', args, this.opts);
  }

  async querySql(sql: string, args: Record<string, unknown> = {}) {
    return mcpToolsCall('query_sql', { sql, ...args }, this.opts);
  }

  /**
   * Run a sandboxed script with the FULL ClientSDK (mutations allowed).
   * The script must `export default async (ctx, client) => ...`.
   * Use `querySdk()` instead for read-only scripts — it gates writes at the
   * tool boundary so a bug in test setup can't accidentally mutate state.
   */
  async runSdk<T = unknown>(script: string, options?: { timeout_ms?: number }): Promise<T> {
    return mcpToolsCall<T>('run_sdk', { script, ...(options ?? {}) }, this.opts);
  }

  /** Read-only counterpart of `runSdk()` — see #432. */
  async querySdk<T = unknown>(script: string, options?: { timeout_ms?: number }): Promise<T> {
    return mcpToolsCall<T>('query_sdk', { script, ...(options ?? {}) }, this.opts);
  }

  /**
   * Issue a raw JSON-RPC method (e.g. `tools/list`). Most callers don't
   * need this — it exists for tests that assert wire-level behavior.
   */
  async raw<T = unknown>(method: string, params?: Record<string, unknown>) {
    return mcpRequest<T>(method, params, this.opts);
  }
}

// ── direct-handler layer (no HTTP) ──────────────────────────────────────

/**
 * Direct-handler test client. Builds the same namespace surface the sandbox
 * exposes, but bypasses HTTP and isolated-vm. Use this for CRUD permutations,
 * error-path edges, and cross-org isolation tests where the MCP wire is not
 * the thing under test.
 */
export class TestApiClient {
  readonly auth_profiles: ReturnType<typeof buildAuthProfilesNamespace>;
  readonly classifiers: ReturnType<typeof buildClassifiersNamespace>;
  readonly connections: ReturnType<typeof buildConnectionsNamespace>;
  readonly entities: ReturnType<typeof buildEntitiesNamespace>;
  readonly entity_schema: ReturnType<typeof buildEntitySchemaNamespace>;
  readonly feeds: ReturnType<typeof buildFeedsNamespace>;
  readonly knowledge: ReturnType<typeof buildKnowledgeNamespace>;
  readonly operations: ReturnType<typeof buildOperationsNamespace>;
  readonly organizations: ReturnType<typeof buildOrganizationsNamespace>;
  readonly view_templates: ReturnType<typeof buildViewTemplatesNamespace>;
  readonly behaviors: ReturnType<typeof buildBehaviorsNamespace>;

  private constructor(
    private readonly env: Env,
    private readonly ctx: ToolContext
  ) {
    this.auth_profiles = buildAuthProfilesNamespace(ctx, env);
    this.classifiers = buildClassifiersNamespace(ctx, env);
    this.connections = buildConnectionsNamespace(ctx, env);
    this.entities = buildEntitiesNamespace(ctx, env);
    this.entity_schema = buildEntitySchemaNamespace(ctx, env);
    this.feeds = buildFeedsNamespace(ctx, env);
    this.knowledge = buildKnowledgeNamespace(ctx, env);
    this.operations = buildOperationsNamespace(ctx, env);
    this.organizations = buildOrganizationsNamespace(ctx);
    this.view_templates = buildViewTemplatesNamespace(ctx, env);
    this.behaviors = buildBehaviorsNamespace(ctx, env);
  }

  /**
   * Create a client bound to a specific auth context. Pass the result of
   * createTestUser/Organization fixtures to set `userId` / `organizationId`.
   * Memberships are checked inside the namespace handlers, so the role and
   * scopes here drive what the client is allowed to do.
   *
   * Triggers workspace-provider initialization on first call (lazy, idempotent).
   */
  static async for(auth: TestClientAuth, env: Partial<Env> = {}): Promise<TestApiClient> {
    await ensureWorkspaceReady();
    const tokenType: TokenType = auth.tokenType ?? (auth.userId !== null ? 'oauth' : 'anonymous');
    const scopedToOrg = auth.scopedToOrg ?? true;
    const ctx: ToolContext = {
      organizationId: auth.organizationId,
      userId: auth.userId,
      memberRole: auth.memberRole,
      agentId: auth.agentId ?? null,
      isAuthenticated: auth.userId !== null,
      clientId: null,
      scopes: auth.scopes ?? ['mcp:read', 'mcp:write', 'mcp:admin'],
      tokenType,
      scopedToOrg,
      // Match production: only OAuth tokens issued without an org-pin can do
      // cross-org reads via `client.org()`.
      allowCrossOrg: tokenType === 'oauth' && !scopedToOrg,
    };
    return new TestApiClient({ ...DEFAULT_TEST_ENV, ...env }, ctx);
  }

  /**
   * Override auth on a fresh client without re-creating fixtures. Useful for
   * verifying that a member role downgrade or scope removal blocks an action.
   * Synchronous because workspace init is already cached after `.for()`.
   */
/**
 * `run_sdk` MCP tool round-trip through the sandbox.
 *
 * Complementary to sandbox/client-sdk-org and namespace-dispatch (which test
 * the SDK directly): this exercises the wire path — JSON-RPC → tool dispatch
 * → isolated-vm → SDK call → response shape.
 *
 * Skipped automatically if isolated-vm cannot load (e.g. local Node 25 without
 * matching prebuilds); CI pins Node 22 where the abi127 prebuild ships.
 */

import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { beforeAll, describe, expect, it } from 'vitest';
import {
  addUserToOrganization,
  createTestAccessToken,
  createTestOAuthClient,
  createTestOrganization,
  createTestUser,
} from '../../setup/test-fixtures';
import { TestApiClient, TestMcpClient } from '../../setup/test-mcp-client';
import { cleanupTestDatabase } from '../../setup/test-db';

function isolatedVmAvailable(): boolean {
  // isolated-vm ships prebuilds for abi127 (Node 22), abi137 (Node 24), and
  // isolated-vm-next for Node 26+. We can't actually try `new Isolate()` to
  // detect — on a wrong ABI it segfaults. Gate on ABI + the package being on
  // disk (bun install optional dep).
  const abi = process.versions.modules;
  const abiOk = abi === '127' || abi === '137' || abi === '147';
  if (!abiOk) return false;
  const root = fileURLToPath(new URL('../../../../../../', import.meta.url));
  return (
    existsSync(join(root, 'node_modules/isolated-vm')) ||
    existsSync(join(root, 'node_modules/isolated-vm-next'))
  );
}

describe('sandbox run (wire)', () => {
  let orgSlug: string;
  let token: string;
  const isolatedAvailable = isolatedVmAvailable();

  beforeAll(async () => {
    await cleanupTestDatabase();

    const org = await createTestOrganization({ name: 'Sandbox Wire Org' });
    const user = await createTestUser({ email: 'sandbox-wire@test.com' });
    await addUserToOrganization(user.id, org.id, 'owner');
    const oauthClient = await createTestOAuthClient();
    const oauthResult = await createTestAccessToken(user.id, org.id, oauthClient.client_id, {
      scope: 'mcp:read mcp:write mcp:admin',
    });

    orgSlug = org.slug;
    token = oauthResult.token;

    const seedClient = await TestApiClient.for({
      organizationId: org.id,
      userId: user.id,
      memberRole: 'owner',
    });
    await seedClient.entity_schema.createType({
      slug: 'company',
      name: 'Company',
    });
    await seedClient.entities.create({ type: 'company', name: 'Sandbox Co' });
  });

  it('runs a trivial script and returns its result', async (testCtx) => {
    if (!isolatedAvailable) return testCtx.skip();
    const client = new TestMcpClient({ token, orgSlug });
    const result = await client.runSdk<unknown>(
      `export default async (_ctx, _client) => ({ ok: true, n: 42 });`
    );
    const json = JSON.stringify(result);
    expect(json).toContain('"ok":true');
    expect(json).toContain('"n":42');
  });

  it('runs a script that calls into client.entities.list (real SDK round-trip)', async (testCtx) => {
    if (!isolatedAvailable) return testCtx.skip();
    const client = new TestMcpClient({ token, orgSlug });
    const result = await client.runSdk<unknown>(
      `export default async (_ctx, client) => {
         const list = await client.entities.list({ entity_type: 'company' });
         return { count: list.entities?.length ?? 0 };
       };`
    );
    const json = JSON.stringify(result);
    // We seeded one company; the script should see it.
    expect(json).toContain('"count":1');
  });

  it('run_sdk can list schedules via client.schedules.list', async (testCtx) => {
    if (!isolatedAvailable) return testCtx.skip();
    const client = new TestMcpClient({ token, orgSlug });
    const result = await client.runSdk<unknown>(
      `export default async (_ctx, client) => {
         const out = await client.schedules.list();
         return { hasSchedules: Array.isArray(out.schedules) };
       };`
    );
    expect(JSON.stringify(result)).toContain('"hasSchedules":true');
  });

  it('query_sdk can list Behaviors via client.behaviors.list', async (testCtx) => {
    if (!isolatedAvailable) return testCtx.skip();
    const client = new TestMcpClient({ token, orgSlug });
    const result = await client.querySdk<unknown>(
      `export default async (_ctx, client) => {
         const out = await client.behaviors.list({ status: 'active' });
				 return { hasBehaviors: Array.isArray(out.behaviors) };
       };`
    );
    expect(JSON.stringify(result)).toContain('"hasBehaviors":true');
  });

  it('run_sdk can create an agent via client.agents.create', async (testCtx) => {
    if (!isolatedAvailable) return testCtx.skip();
    const client = new TestMcpClient({ token, orgSlug });
    const result = await client.runSdk<unknown>(
      `export default async (_ctx, client) => {
         const out = await client.agents.create({
           agent_id: 'wire-test-agent',
           name: 'Wire Test Agent',
         });
         return out;
       };`,
      { timeout_ms: 15_000 }
    );
    expect(JSON.stringify(result)).toContain('"action":"create"');
